function shiftYear(s,n){if(!s)return '';const[y,m,d]=s.split('-').map(Number);return (y+n)+'-'+String(m).padStart(2,'0')+'-'+String(d).padStart(2,'0');}
function daysDiff(a,b){return Math.round((new Date(a+'T00:00:00Z')-new Date(b+'T00:00:00Z'))/86400000);}
/* 'YYYY-MM-DD' → 'M/D' (연도·앞자리 0 생략) — 일자별 표/차트 라벨 공통 포맷 */
function mdLabel(d){ return d? (+d.slice(5,7))+'/'+(+d.slice(8,10)) : ''; }
/* 시트에 직전/전년이 비어있을 때만 보강: 직전=동일유형 직전 행사, 전년=동일유형 약 1년 전 행사 */
function derivePrevYoy(promos){
  const sorted=promos.slice().sort((a,b)=>a.start.localeCompare(b.start));
  promos.forEach(p=>{
    if(!p.prevStart){let best=null;sorted.forEach(q=>{if(q!==p&&q.type===p.type&&q.start<p.start){if(!best||q.start>best.start)best=q;}});if(best){p.prevStart=best.start;p.prevEnd=best.end;}}
    if(!p.yoyStart){const tgt=shiftYear(p.start,-1);let best=null,bd=Infinity;promos.forEach(q=>{if(q!==p&&q.type===p.type){const d=Math.abs(daysDiff(q.start,tgt));if(d<bd&&d<=45){bd=d;best=q;}}});if(best){p.yoyStart=best.start;p.yoyEnd=best.end;}}
  });
  // 매칭되는 프로모션 id(라벨 표기용)
  promos.forEach(p=>{const fp=promos.find(q=>q.start===p.prevStart);if(fp)p.prevId=fp.id;const fy=promos.find(q=>q.start===p.yoyStart);if(fy)p.yoyId=fy.id;});
  return promos;
}
