/* 일자별 상세 표(섹션2) 공용 헤더 — 지표그룹 N개 × 7열(금번/직전/전년/직전차/직전비/전년차/전년비) */
function cmpDailyHead(groups){
  return '<thead><tr><th rowspan="2">일자</th>'+groups.map(g=>`<th colspan="7" class="gdiv gh">${g}</th>`).join('')+'</tr><tr>'+
    groups.map(()=>'<th class="gdiv">금번</th><th>직전</th><th>전년</th><th>직전차</th><th>직전비</th><th>전년차</th><th>전년비</th>').join('')+
    '</tr></thead>';
}
/* 일자별 표(섹션2) 중 일부 지표는 7열 전체가 아니라 축약된 열만 보여달라는 요청에 따른 변형들.
   width3: 금번/직전비/전년비만(값 자체·차이 생략) — 매출용, "비"는 상대변화율(delta()).
   width5: 금번/직전/전년/직전비/전년비(차이만 생략) — 전환율·신규비중·기존비중용, "비"는 이미
   %인 값의 차이이므로 %p(deltaP()) — cmp5TDs 참고. */
function cmpVarHead(groups){ // groups: [{label, width:3|5|7}]
  return '<thead><tr><th rowspan="2">일자</th>'+groups.map(g=>`<th colspan="${g.width}" class="gdiv gh">${g.label}</th>`).join('')+'</tr><tr>'+
    groups.map(g=>{
      if(g.width===3) return '<th class="gdiv">금번</th><th>직전비</th><th>전년비</th>';
      if(g.width===5) return '<th class="gdiv">금번</th><th>직전</th><th>전년</th><th>직전비</th><th>전년비</th>';
      return '<th class="gdiv">금번</th><th>직전</th><th>전년</th><th>직전차</th><th>직전비</th><th>전년차</th><th>전년비</th>';
    }).join('')+
    '</tr></thead>';
}
function cmp3TDs(curV,prevV,yoyV,fmt){
  fmt=fmt||f0;
  const v=x=>x==null?'—':fmt(x);
  const rP=delta(curV,prevV), rY=delta(curV,yoyV);
  return `<td class="gdiv">${v(curV)}</td><td class="${rP.c}">${rP.t}</td><td class="${rY.c}">${rY.t}</td>`;
}
/* cmp5TDs는 전환율/신규비중/기존비중처럼 이미 %인 지표에만 쓰인다 — 그 차이는 상대변화율(%)이
   아니라 %p(퍼센트포인트)로 표기해야 한다(예: 전환율 5.8%→9.5%는 "-3.7%"가 아니라 "-3.7%p"). */
function cmp5TDs(curV,prevV,yoyV,fmt){
  fmt=fmt||f0;
  const v=x=>x==null?'—':fmt(x);
  const rP=deltaP(curV,prevV), rY=deltaP(curV,yoyV);
  return `<td class="gdiv">${v(curV)}</td><td>${v(prevV)}</td><td>${v(yoyV)}</td><td class="${rP.c}">${rP.t}</td><td class="${rY.c}">${rY.t}</td>`;
}

function renderD(){
  const id=document.getElementById('d-promo').value;const p=promoById(id);if(!p)return;
  document.getElementById('d-period').textContent=`${p.start} ~ ${p.end}`;
  const AGG=computeAgg('shop',p);
  const {cur,prev,yoy,rows,prevAgg,yoyAgg,enriched}=AGG;
  document.getElementById('d-band').innerHTML=bandHTML([
    {k:'금번',s:p.start,e:p.end},
    {k:'직전',s:p.prevStart,e:p.prevEnd,note:p.prevId?promoLabelShort(p.prevId):''},
    {k:'전년',s:p.yoyStart,e:p.yoyEnd,note:p.yoyId?promoLabelShort(p.yoyId):''},
  ]);

  /* ===== 1. 프로모션 일별 누계 실적 ===== */
  document.getElementById('d-kpi-title').textContent=`${p.label} 누계 실적`;
  const KPI_METRICS=[
    {l:'매출',    get:a=>a.rev,                 fmt:fy,  ratio:false},
    {l:'주문건수', get:a=>a.ord,                 fmt:f0,  ratio:false},
    {l:'판매수량', get:a=>a.qty,                 fmt:f0,  ratio:false},
    {l:'UV',      get:a=>a.uv,                  fmt:f0,  ratio:false},
    {l:'객단가',   get:a=>aov(a),                fmt:fy,  ratio:false},
    {l:'신규비중', get:a=>hasNO(a)?newR(a):null, fmt:fp0, ratio:true},
    {l:'기존비중', get:a=>hasNO(a)?oldR(a):null, fmt:fp0, ratio:true},
  ];
  document.getElementById('d-kpi').innerHTML = TRAFFIC_TABLE_HEAD+'<tbody>'+
    KPI_METRICS.map(m=>cmp7Row(m.l, m.get(cur), prev?m.get(prev):null, yoy?m.get(yoy):null, m.fmt, m.ratio)).join('')+
    '</tbody>';
  document.getElementById('d-ai-cum').innerHTML=renderSalesInsightHTML('shop',p,AGG,'all',null);
  renderMemoBox('daily-cum', p.id+'::shop');

  /* ===== 2. 프로모션 일자별 상세 실적 ===== */
  document.getElementById('d-daily-title').textContent=`${p.label} 일자별 실적`;
  setChart('d-chart',{data:{labels:rows.map(r=>mdLabel(r.d)),datasets:[
    {type:'bar',label:'매출',data:rows.map(r=>r.rev),backgroundColor:'#378ADD',yAxisID:'y'},
    {type:'line',label:'주문건수',data:rows.map(r=>r.ord),borderColor:'#D85A30',borderDash:[5,4],pointBackgroundColor:'#D85A30',tension:.3,yAxisID:'y1'}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>c.dataset.label+': '+c.parsed.y.toLocaleString('en-US')}}},
    scales:{y:{position:'left',ticks:{callback:v=>v.toLocaleString('en-US')}},y1:{position:'right',grid:{drawOnChartArea:false},ticks:{callback:v=>v.toLocaleString('en-US')}}}}});

  /* 표 A: 매출(금번/직전비/전년비만) · 주문건수 · 판매수량(7열) */
  let tA=cmpVarHead([{label:'매출',width:3},{label:'주문건수',width:7},{label:'판매수량',width:7}])+'<tbody>';
  enriched.forEach(({r,pO,yO})=>{
    tA+=`<tr><td>${mdLabel(r.d)}</td>`+
      cmp3TDs(r.rev,pO?pO.rev:null,yO?yO.rev:null,fy)+
      cmp7TDs(r.ord,pO?pO.ord:null,yO?yO.ord:null,f0,false)+
      cmp7TDs(r.qty,pO?pO.qty:null,yO?yO.qty:null,f0,false)+
      '</tr>';
  });
  tA+=`<tr class="total"><td>합계</td>`+
    cmp3TDs(cur.rev,prevAgg?prevAgg.rev:null,yoyAgg?yoyAgg.rev:null,fy)+
    cmp7TDs(cur.ord,prevAgg?prevAgg.ord:null,yoyAgg?yoyAgg.ord:null,f0,false)+
    cmp7TDs(cur.qty,prevAgg?prevAgg.qty:null,yoyAgg?yoyAgg.qty:null,f0,false)+
    '</tr></tbody>';
  document.getElementById('d-tbl').innerHTML=tA;

  /* 표 B: UV(7열) · 전환율·신규비중·기존비중(금번/직전/전년/직전비/전년비, 차이 열 생략) */
  const convOf=o=>o.uv?o.ord/o.uv:0;
  let tB=cmpVarHead([{label:'UV',width:7},{label:'전환율',width:5},{label:'신규비중',width:5},{label:'기존비중',width:5}])+'<tbody>';
  enriched.forEach(({r,pO,yO})=>{
    tB+=`<tr><td>${mdLabel(r.d)}</td>`+
      cmp7TDs(r.uv,pO?pO.uv:null,yO?yO.uv:null,f0,false)+
      cmp5TDs(convOf(r),pO?convOf(pO):null,yO?convOf(yO):null,fp1)+
      cmp5TDs(hasNO(r)?newR(r):null,pO&&hasNO(pO)?newR(pO):null,yO&&hasNO(yO)?newR(yO):null,fp0)+
      cmp5TDs(hasNO(r)?oldR(r):null,pO&&hasNO(pO)?oldR(pO):null,yO&&hasNO(yO)?oldR(yO):null,fp0)+
      '</tr>';
  });
  tB+=`<tr class="total"><td>합계</td>`+
    cmp7TDs(cur.uv,prevAgg?prevAgg.uv:null,yoyAgg?yoyAgg.uv:null,f0,false)+
    cmp5TDs(convOf(cur),prevAgg?convOf(prevAgg):null,yoyAgg?convOf(yoyAgg):null,fp1)+
    cmp5TDs(hasNO(cur)?newR(cur):null,prevAgg&&hasNO(prevAgg)?newR(prevAgg):null,yoyAgg&&hasNO(yoyAgg)?newR(yoyAgg):null,fp0)+
    cmp5TDs(hasNO(cur)?oldR(cur):null,prevAgg&&hasNO(prevAgg)?oldR(prevAgg):null,yoyAgg&&hasNO(yoyAgg)?oldR(yoyAgg):null,fp0)+
    '</tr></tbody>';
  document.getElementById('d-tbl2').innerHTML=tB;

  const lastDayIdx=enriched.length?enriched.length-1:null;
  document.getElementById('d-ai').innerHTML=renderSalesInsightHTML('shop',p,scopeAggByDay(AGG,'day',lastDayIdx),'day',lastDayIdx);
  renderMemoBox('daily', p.id+'::shop');

  /* ===== 3. 메인 SKU 누계 카드 (고정 4개 SKU — 원하는 SKU는 아래 "추가 SKU 카드"로) ===== */
  document.getElementById('d-sku-daybtns').innerHTML=
    `<button type="button" class="tab${dSkuDayIdx==null?' active':''}" data-day="__ALL__">누계</button>`+
    enriched.map((e,i)=>`<button type="button" class="tab${dSkuDayIdx===i?' active':''}" data-day="${i}">${i+1}일차</button>`).join('');
  // dSkuDayIdx===null(누계 버튼) → 전체 기간 누계, 그 외(N일차 버튼) → 해당 하루만(누적 아님).
  const skuMode = dSkuDayIdx==null ? 'cum' : 'day';
  {
    const skuCumAGG=scopeAggByDay(AGG,skuMode,dSkuDayIdx);
    const srs=[skuCumAGG.cur.rev, skuCumAGG.prevAgg?skuCumAGG.prevAgg.rev:null, skuCumAGG.yoyAgg?skuCumAGG.yoyAgg.rev:null];
    document.getElementById('d-skugrid').innerHTML=SKU_KEYS.map(k=>{
      const cum=scopeAggByDay(computeAgg(k,p),skuMode,dSkuDayIdx);
      const vs=[cum.rows.length?cum.cur:null, cum.prevAgg, cum.yoyAgg];
      return renderSkuSummaryCardHTML({title:skuCodeLabel(k),colLabels:['금번','직전','전년'],vs,srs});
    }).join('');
  }
  document.getElementById('d-ai-mainsku').innerHTML=renderMainSkuInsightHTML(p,skuMode,dSkuDayIdx);
  renderMemoBox('daily-mainsku', p.id+'::shop');

  /* ===== 4. 추가 SKU 카드 (메인 SKU 카드와 동일한 누계/일차 버튼 상태를 공유) ===== */
  renderAddSkuManagerHTML();
  renderAddSkuGrid(dSkuDayIdx);
  document.getElementById('d-ai-addsku').innerHTML=renderAddSkuInsightHTML(dSkuDayIdx);
}

/* TAB 5 (연간 데이터) */
function renderY(){
  const yearEl=document.getElementById('y-year');if(!yearEl)return;
  const year=yearEl.value;
  const ms=months().filter(m=>m.slice(0,4)===year);
  if(!ms.length){document.getElementById('y-kpi').innerHTML='';document.getElementById('y-shop-tbl').innerHTML='';document.getElementById('y-skugrid').innerHTML='';return;}
  const tot=shopSum(ms.flatMap(m=>shopMonth(m)));
  const K=[
    {l:'매출',f:fy,g:a=>a.rev},{l:'주문건수',f:f0,g:a=>a.ord},{l:'판매수량',f:f0,g:a=>a.qty},
    {l:'UV',f:f0,g:a=>a.uv},{l:'객단가',f:fy,g:aov},
    {l:'신규비중',f:x=>hasNO(tot)?fp0(x):'—',g:newR},{l:'기존비중',f:x=>hasNO(tot)?fp0(x):'—',g:oldR},
  ];
  document.getElementById('y-kpi').innerHTML=K.map(m=>`<div class="kpi"><div class="lbl">${m.l}</div><div class="val">${m.f(m.g(tot))}</div></div>`).join('');
  setChart('y-chart',{type:'bar',data:{labels:ms.map(m=>(+m.slice(5))+'월'),datasets:[{data:ms.map(m=>shopSum(shopMonth(m)).rev),backgroundColor:'#378ADD'}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>fy(c.parsed.y)}}},scales:{y:{ticks:{callback:v=>v.toLocaleString('en-US')}}}}});
  let t='<thead><tr><th>월</th><th>매출</th><th>목표매출</th><th>계획비</th><th>주문</th><th>판매수량</th><th>UV</th><th>객단가</th><th>신규%</th><th>기존%</th></tr></thead><tbody>';
  let goalSum=0;
  ms.forEach(m=>{const a=shopSum(shopMonth(m));
    const goal=monthlyGoalForYm(m),rate=planRateOf(a.rev,goal);
    if(goal>0)goalSum+=goal;
    t+=`<tr><td>${+m.slice(5)}월</td><td>${f0(a.rev)}</td><td>${goal>0?f0(goal):'-'}</td><td><span class="${planRateColor(rate)}">${planRateStr(rate)}</span></td><td>${f0(a.ord)}</td><td>${f0(a.qty)}</td><td>${f0(a.uv)}</td><td>${a.ord?f0(a.rev/a.ord):'-'}</td><td>${hasNO(a)?fp0(newR(a)):'-'}</td><td>${hasNO(a)?fp0(oldR(a)):'-'}</td></tr>`;});
  const totRate=planRateOf(tot.rev,goalSum);
  t+=`<tr class="total"><td>합계</td><td>${f0(tot.rev)}</td><td>${goalSum>0?f0(goalSum):'-'}</td><td><span class="${planRateColor(totRate)}">${planRateStr(totRate)}</span></td><td>${f0(tot.ord)}</td><td>${f0(tot.qty)}</td><td>${f0(tot.uv)}</td><td>${tot.ord?f0(tot.rev/tot.ord):'-'}</td><td>${hasNO(tot)?fp0(newR(tot)):'-'}</td><td>${hasNO(tot)?fp0(oldR(tot)):'-'}</td></tr>`;
  document.getElementById('y-shop-tbl').innerHTML=t+'</tbody>';
  document.getElementById('y-skugrid').innerHTML=SKU_KEYS.map(k=>{
    let tt=`<div class="skucard"><h4>${k}</h4><table><thead><tr><th>월</th><th>매출</th><th>주문</th><th>판매수량</th><th>PV</th><th>UV</th><th>객단가</th><th>신규%</th><th>기존%</th></tr></thead><tbody>`;
    const sumA={rev:0,ord:0,qty:0,pv:0,uv:0,nc:0,oc:0,hasOrd:false};
    ms.forEach(m=>{const a=skuSum(skuMonth(k,m));
      ['rev','ord','qty','pv','uv','nc','oc'].forEach(f=>sumA[f]+=a[f]);
      if(a.hasOrd)sumA.hasOrd=true;
      tt+=`<tr><td>${+m.slice(5)}월</td><td>${f0(a.rev)}</td><td>${a.hasOrd?f0(a.ord):'-'}</td><td>${f0(a.qty)}</td><td>${f0(a.pv)}</td><td>${f0(a.uv)}</td><td>${a.hasOrd&&a.ord?f0(a.rev/a.ord):'-'}</td><td>${hasNO(a)?fp0(newR(a)):'-'}</td><td>${hasNO(a)?fp0(oldR(a)):'-'}</td></tr>`;});
    tt+=`<tr class="total"><td>합계</td><td>${f0(sumA.rev)}</td><td>${sumA.hasOrd?f0(sumA.ord):'-'}</td><td>${f0(sumA.qty)}</td><td>${f0(sumA.pv)}</td><td>${f0(sumA.uv)}</td><td>${sumA.hasOrd&&sumA.ord?f0(sumA.rev/sumA.ord):'-'}</td><td>${hasNO(sumA)?fp0(newR(sumA)):'-'}</td><td>${hasNO(sumA)?fp0(oldR(sumA)):'-'}</td></tr>`;
    return tt+'</tbody></table></div>';
  }).join('');
  renderMemoBox('yearly', year);
}

/* TAB 4 */
let selected=[];
function defaultSelected(){
  const want=['26-6-슈퍼세일','26-3-슈퍼세일','25-6-슈퍼세일'].filter(id=>promoById(id));
  if(want.length)return want;
  return promosSorted().slice(0,3).map(p=>p.id);
}
function renderChips(){
  const box=document.getElementById('c-chips');
  box.innerHTML=selected.map((id,i)=>{const p=promoById(id);const col=COLORS[i%COLORS.length];
    return `<span class="chip" style="border-color:${col};color:${col};background:${col}14"><span>${p?p.label:id}</span><b data-rm="${id}">×</b></span>`;}).join('')||'<span class="muted-note">프로모션을 추가하세요</span>';
  box.querySelectorAll('b[data-rm]').forEach(b=>b.onclick=()=>{selected=selected.filter(x=>x!==b.dataset.rm);renderChips();fillAdd();renderC();});
}
function fillAdd(){
  const sel=document.getElementById('c-add');
  const rest=promosSorted().filter(p=>!selected.includes(p.id));
  sel.innerHTML='<option value="">선택…</option>'+rest.map(p=>`<option value="${p.id}">${p.label}</option>`).join('');
}
function maxLenSel(){return Math.max(1,...selected.map(id=>promoLen(promoById(id))));}
function elapsed(id,getter,dm){const p=promoById(id);const len=promoLen(p);const ML=maxLenSel();const out=[];for(let k=0;k<ML;k++){if(k<len){const r=dm[addDays(p.start,k)];out.push(r?getter(r):null);}else out.push(null);}return out;}
function renderCBand(){
  const el=document.getElementById('c-band');if(!el)return;
  const baseSel=document.getElementById('c-base');
  const baseId=(baseSel&&baseSel.value)||selected[0];
  const p=promoById(baseId);
  if(!p){el.innerHTML='';return;}
  el.innerHTML=bandHTML([
    {k:'금번',s:p.start,e:p.end,note:promoLabelShort(p.id)},
    {k:'직전',s:p.prevStart,e:p.prevEnd,note:p.prevId?promoLabelShort(p.prevId):''},
    {k:'전년',s:p.yoyStart,e:p.yoyEnd,note:p.yoyId?promoLabelShort(p.yoyId):''},
  ]);
}
/* ---- 그외 SKU(신규) — 현재 비교 중인(selected) 프로모션들 중 하나라도 데이터가 있는
   그외 SKU만 #c-sku 드롭다운에 추가한다. c-skugrid와 동일한 "합집합" 기준. ---- */
function refreshCSkuOptions(){
  const sel=document.getElementById('c-sku'); if(!sel) return;
  const promos=selected.map(id=>promoById(id)).filter(Boolean);
  const codeSet=new Set();
  promos.forEach(p=>otherSkuCodesForRange(p.start,p.end).forEach(c=>codeSet.add(c)));
  const keep=sel.value||SKU_KEYS[0];
  sel.querySelectorAll('option[data-dynamic-sku="1"]').forEach(o=>o.remove());
  [...codeSet].forEach(code=>{
    const opt=document.createElement('option');
    opt.value=code; opt.textContent=otherSkuLabel(code); opt.dataset.dynamicSku='1';
    sel.appendChild(opt);
  });
  if(keep && [...sel.options].some(o=>o.value===keep)) sel.value=keep;
}

/* ── SKU 비교 그룹 — "상품번호"가 아니라 MD가 정의한 동일 마케팅 포지션(예: CPS 상품) 기준으로
   묶어서 비교하기 위한 기능. 같은 포지션이 프로모션마다 다른 상품코드를 쓰는 경우(예: 8월
   카미토쿠="미용신CPS", 5월 카미토쿠="히촌CPS") 상품코드가 달라도 한 카드에서 비교할 수 있다.
   서버/DB가 없는 정적 사이트라 다른 사용자 입력(메모 등)과 동일하게 브라우저 localStorage에만
   저장한다(기기·브라우저 간 공유 안 됨). 그룹 = {id,label,codes:[상품코드...]} — 코드 자체가
   "동일 포지션으로 취급할 상품코드 집합"이며, 특정 프로모션에 고정 매핑되지 않는다: 어떤
   프로모션에 대해 카드 값을 계산할 땐 codes 중 그 프로모션 기간에 실제 데이터가 있는 코드를
   찾아 쓴다(여러 개 매칭되면 합산, 하나도 없으면 그 칸은 '—'). */
const SKU_GROUP_KEY='rakutenSkuCompareGroups_v1';
function loadSkuGroups(){ try{ const a=JSON.parse(localStorage.getItem(SKU_GROUP_KEY)||'[]'); return Array.isArray(a)?a:[]; }catch(e){ return []; } }
function saveSkuGroups(list){ try{ localStorage.setItem(SKU_GROUP_KEY, JSON.stringify(list)); }catch(e){ console.warn('[SKU 비교 그룹] 저장 실패(localStorage 사용 불가):', e.message); } }
function skuGroupNewId(){ return 'g'+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }
/* 그룹이 특정 프로모션 p에 대해 갖는 값 — codes 중 p 기간에 실제 데이터가 있는 코드를 전부
   찾아 합산한다(skuRangeSafe라 그룹에 저장된 코드가 이후 data.json 갱신으로 사라져도 안전). */
function resolveGroupColumn(group,p){
  const matched=(group.codes||[]).filter(code=>skuRangeSafe(code,p.start,p.end).length>0);
  if(!matched.length) return {v:null,codes:[]};
  const rows=matched.flatMap(code=>skuRangeSafe(code,p.start,p.end));
  return {v:skuSum(rows),codes:matched};
}
/* aggs(현재 비교 중인 프로모션들)에서 1개 이상 매칭되는 그룹들이 포함하는 모든 코드 —
   해당 코드는 개별 카드로 중복 표시하지 않기 위한 집합. */
function codesCoveredByActiveGroups(groups,aggs){
  const set=new Set();
  groups.forEach(g=>{ if(aggs.some(o=>resolveGroupColumn(g,o.p).codes.length)) (g.codes||[]).forEach(c=>set.add(c)); });
  return set;
}
function renderSkuGroupManagerHTML(){
  const wrap=document.getElementById('c-grp-mgr'); if(!wrap) return;
  const groups=loadSkuGroups();
  const codeOpts=allSkuCodes().map(c=>`<option value="${c}">${skuCodeLabel(c)}</option>`).join('');
  const list=groups.length? groups.map(g=>`
    <div class="grp-item" data-id="${g.id}">
      <div class="grp-item-label">${g.label}</div>
      <div class="grp-item-codes">${(g.codes||[]).map(c=>skuCodeLabel(c)).join(' · ')}</div>
      <div class="grp-item-actions"><button type="button" class="btn grp-del-btn" data-id="${g.id}">삭제</button></div>
    </div>`).join('') : '<div class="muted-note">등록된 비교 그룹이 없습니다.</div>';
  wrap.innerHTML=`
    <div class="grp-list">${list}</div>
    <button type="button" class="btn grp-add-btn">+ 비교 그룹 추가</button>
    <div class="grp-add-wrap" style="display:none">
      <input type="text" class="grp-add-label" placeholder="그룹명 (예: CPS 비교)">
      <select class="grp-add-codes" multiple size="6">${codeOpts}</select>
      <div class="muted-note">Ctrl(⌘)+클릭으로 이 포지션에 해당하는 상품코드를 모두 선택하세요.</div>
      <div class="memo-entry-actions">
        <button type="button" class="btn grp-add-save">저장</button>
        <button type="button" class="btn grp-add-cancel">취소</button>
      </div>
    </div>`;
}
function wireSkuGroupManager(){
  const wrap=document.getElementById('c-grp-mgr'); if(!wrap || wrap.dataset.grpWired) return;
  wrap.dataset.grpWired='1';
  wrap.addEventListener('click',(e)=>{
    const addBtn=e.target.closest('.grp-add-btn');
    const saveBtn=e.target.closest('.grp-add-save');
    const cancelBtn=e.target.closest('.grp-add-cancel');
    const delBtn=e.target.closest('.grp-del-btn');
    if(addBtn){
      wrap.querySelector('.grp-add-wrap').style.display='flex';
    } else if(cancelBtn){
      wrap.querySelector('.grp-add-wrap').style.display='none';
    } else if(saveBtn){
      const label=wrap.querySelector('.grp-add-label').value.trim();
      const codes=[...wrap.querySelector('.grp-add-codes').selectedOptions].map(o=>o.value);
      if(!label||!codes.length){ alert('그룹명과 상품코드를 1개 이상 선택해주세요.'); return; }
      const groups=loadSkuGroups();
      groups.push({id:skuGroupNewId(), label, codes});
      saveSkuGroups(groups);
      renderC();
    } else if(delBtn){
      if(!confirm('이 비교 그룹을 삭제할까요?')) return;
      saveSkuGroups(loadSkuGroups().filter(g=>g.id!==delBtn.dataset.id));
      renderC();
    }
  });
}

function renderC(){
  refreshCSkuOptions();
  renderCBand();
  const sh=document.getElementById('c-shop');
  if(!selected.length){sh.innerHTML='';return;}
  const aggs=selected.map(id=>{const p=promoById(id);return{id,p,a:shopSum(shopRange(p.start,p.end))};});
  const rowsDef=[
    {l:'매출',f:a=>fy(a.rev),g:a=>a.rev},
    {l:'주문건수',f:a=>f0(a.ord),g:a=>a.ord},
    {l:'판매수량',f:a=>f0(a.qty),g:a=>a.qty},
    {l:'UV',f:a=>f0(a.uv),g:a=>a.uv},
    {l:'객단가',f:a=>fy(aov(a)),g:a=>aov(a)},
    {l:'신규비중',f:a=>shareNew(a),g:a=>newR(a),pct:true,no:true},
    {l:'기존비중',f:a=>shareOld(a),g:a=>oldR(a),pct:true,no:true},
  ];
  const A0=aggs[0]&&aggs[0].a,A1=aggs[1]&&aggs[1].a,A2=aggs[2]&&aggs[2].a;
  let th='<thead><tr><th>지표</th>'+aggs.map((o,i)=>`<th style="color:${COLORS[i%COLORS.length]}">${o.p.label}</th>`).join('')+'<th>직전비</th><th>전년비</th></tr></thead><tbody>';
  rowsDef.forEach(m=>{
    const cells=aggs.map(o=>`<td>${m.f(o.a)}</td>`).join('');
    const okP=A1&&(!m.no||hasNO(A1)),okY=A2&&(!m.no||hasNO(A2));
    const dP=m.pct?deltaP(m.g(A0),A1?m.g(A1):null,okP):delta(m.g(A0),A1?m.g(A1):null,okP);
    const dY=m.pct?deltaP(m.g(A0),A2?m.g(A2):null,okY):delta(m.g(A0),A2?m.g(A2):null,okY);
    th+=`<tr><td>${m.l}</td>${cells}<td class="${dP.c}">${dP.t}</td><td class="${dY.c}">${dY.t}</td></tr>`;
  });
  sh.innerHTML=th+'</tbody>';
  setChart('c-bar',{type:'bar',data:{labels:aggs.map(o=>o.p.label),datasets:[{data:aggs.map(o=>o.a.rev),backgroundColor:aggs.map((o,i)=>COLORS[i%COLORS.length])}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>fy(c.parsed.y)}}},scales:{y:{ticks:{callback:v=>v.toLocaleString('en-US')}}}}});
  const labels=Array.from({length:maxLenSel()},(_,k)=>(k+1)+'일차');
  const sMet={'매출':'rev','주문건수':'ord','판매수량':'qty','UV':'uv'}[document.getElementById('c-metric').value]||'rev';
  setChart('c-line',{type:'line',data:{labels,datasets:aggs.map((o,i)=>({label:o.p.label,data:elapsed(o.id,r=>r[sMet],shopDM),borderColor:COLORS[i%COLORS.length],pointBackgroundColor:COLORS[i%COLORS.length],borderDash:i===1?[6,4]:i===2?[2,3]:[],tension:.3,spanGaps:true}))},
    options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{mode:'index',intersect:false,itemSort:(a,b)=>b.parsed.y-a.parsed.y,callbacks:{label:c=>c.parsed.y==null?null:c.dataset.label+': '+c.parsed.y.toLocaleString('en-US')}}},scales:{y:{ticks:{callback:v=>v.toLocaleString('en-US')}}}}});
  document.getElementById('c-line-lg').innerHTML=aggs.map((o,i)=>`<span><i style="border-color:${COLORS[i%COLORS.length]}"></i>${o.p.label}</span>`).join('');
  const sk=document.getElementById('c-sku').value||SKU_KEYS[0];const skMet={'매출':'rev','판매수량':'qty','UV':'pv'}[document.getElementById('c-sku-metric').value]||'rev';
  setChart('c-sku-line',{type:'line',data:{labels,datasets:aggs.map((o,i)=>({label:o.p.label,data:elapsed(o.id,r=>r[skMet],skuDM[sk]),borderColor:COLORS[i%COLORS.length],pointBackgroundColor:COLORS[i%COLORS.length],borderDash:i===1?[6,4]:i===2?[2,3]:[],tension:.3,spanGaps:true}))},
    options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{mode:'index',intersect:false,itemSort:(a,b)=>b.parsed.y-a.parsed.y,callbacks:{label:c=>c.parsed.y==null?null:c.dataset.label+': '+c.parsed.y.toLocaleString('en-US')}}},scales:{y:{ticks:{callback:v=>v.toLocaleString('en-US')}}}}});
  document.getElementById('c-sku-lg').innerHTML=aggs.map((o,i)=>`<span><i style="border-color:${COLORS[i%COLORS.length]}"></i>${o.p.label}</span>`).join('');
  renderSkuGroupManagerHTML();
  const colLabels=aggs.map(o=>shortLabel(o.p)), srs=aggs.map(o=>o.a.rev);
  const buildCodeCard=(k,label)=>{
    const rows=aggs.map(o=>skuRange(k,o.p.start,o.p.end));
    const vs=rows.map(r=>r.length?skuSum(r):null);
    return renderSkuSummaryCardHTML({title:label,colLabels,colColors:COLORS,vs,srs});
  };
  const groups=loadSkuGroups();
  const activeGroups=groups.filter(g=>aggs.some(o=>resolveGroupColumn(g,o.p).codes.length));
  const covered=codesCoveredByActiveGroups(groups,aggs);
  const buildGroupCard=(g)=>{
    const resolved=aggs.map(o=>resolveGroupColumn(g,o.p));
    const vs=resolved.map(r=>r.v);
    const KLABELS=['금번','직전','전년'];
    const subtitle=resolved.map((r,i)=>`${KLABELS[i]||('표시'+(i+1))}: ${r.codes.length?r.codes.map(skuCodeLabel).join('+')+`(${shortLabel(aggs[i].p)})`:'-'}`).join(' · ');
    return renderSkuSummaryCardHTML({title:g.label,subtitleHTML:subtitle,colLabels,colColors:COLORS,vs,srs});
  };
  const otherCodesInAggs=[...new Set(aggs.flatMap(o=>otherSkuCodesForRange(o.p.start,o.p.end)))];
  document.getElementById('c-skugrid').innerHTML=
    activeGroups.map(buildGroupCard).join('') +
    SKU_KEYS.filter(k=>!covered.has(k)).map(k=>buildCodeCard(k,k)).join('') +
    otherCodesInAggs.filter(k=>!covered.has(k)).map(k=>buildCodeCard(k,otherSkuLabel(k))).join('');
  renderMemoBox('compare', (document.getElementById('c-base')||{}).value||'');
}

