/* live fetch: GitHub의 data.json에서 읽어옴 (Google Sheets → Apps Script → GitHub 경유, gviz 미사용) */
function latestDate(){let mx='';DATA.shop.forEach(r=>{if(r.d>mx)mx=r.d;});SKU_KEYS.forEach(k=>(DATA.sku[k]||[]).forEach(r=>{if(r.d>mx)mx=r.d;}));return mx;}
function setStatus(s,msg){const b=document.getElementById('status');b.className='badge '+(s==='live'?'live':s==='load'?'load':'snap');
  b.textContent=s==='live'?'실시간 연동됨':s==='load'?'불러오는 중…':'스냅샷';
  const last=latestDate();
  const t=new Date().toLocaleTimeString('ko-KR',{hour12:false});
  document.getElementById('asof').textContent=(s==='live'?'시트 기준 · 최신 '+last+' · '+t+' 갱신':s==='load'?'시트에서 읽는 중…':'내장 데이터 · 최신 '+last)+((s==='snap'||s==='live')&&msg?' ('+msg+')':'');}
function num(v){if(v==null)return 0;const s=String(v).replace(/,/g,'').trim();if(s===''||s[0]==='#')return 0;const n=parseFloat(s);return isFinite(n)?n:0;}
/* 연도 유효범위 밖(예: 컬럼이 잘못 매핑되어 순번/매출 등 엉뚱한 값이 날짜로 파싱된 경우) 결과는
   전부 무효 처리한다 — 예) new Date("8612")가 "8612-01-01"을 반환하는 것처럼, JS Date는 4자리 숫자
   문자열을 연도로 오인식하는 경우가 있어 이 가드가 없으면 그런 값이 그대로 통과되어 전체 파이프라인
   (정렬·최신일자·합계)이 조용히 깨진다. */
const DATE_YEAR_MIN=2015, DATE_YEAR_MAX=2035;
function normDate(v){if(v==null)return '';if(v instanceof Date)return v.toISOString().slice(0,10);
  if(typeof v==='number'&&v>20000&&v<80000){const ms=Date.UTC(1899,11,30)+Math.round(v)*86400000;return validYear(new Date(ms).toISOString().slice(0,10));}
  const s=String(v).trim();let m;
  m=s.match(/^Date\((\d+),(\d+),(\d+)/);if(m)return validYear(m[1]+'-'+String(+m[2]+1).padStart(2,'0')+'-'+String(m[3]).padStart(2,'0'));
  m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return validYear(m[1]+'-'+m[2]+'-'+m[3]);
  m=s.match(/^(\d{4})\D+(\d{1,2})\D+(\d{1,2})/);if(m)return validYear(m[1]+'-'+String(m[2]).padStart(2,'0')+'-'+String(m[3]).padStart(2,'0'));
  m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);if(m)return validYear(m[3]+'-'+String(m[1]).padStart(2,'0')+'-'+String(m[2]).padStart(2,'0'));
  /* "2026.5"처럼 연·월만 있고 일(day)이 없는 값은 절대 유효한 하루치 날짜로 취급하지 않는다.
     시트에 월간/이벤트 합계 행이 이런 표기("YYYY.M")로 섞여 있을 때, 아래 new Date(s) 폴백이
     이를 "그 달 1일"로 잘못 해석해 월 전체 합계가 하루치 데이터로 둔갑해 이중 집계되는 사고를 막는다. */
  if(/^\d{4}[.\-/]\d{1,2}$/.test(s)) return '';
  const d=new Date(s);return isNaN(d)?'':validYear(d.toISOString().slice(0,10));}
function validYear(dateStr){if(!dateStr)return '';const y=+dateStr.slice(0,4);return(y>=DATE_YEAR_MIN&&y<=DATE_YEAR_MAX)?dateStr:'';}
/* GitHub의 data.json 하나를 가져온다. 캐시를 우회하기 위해 매번 타임스탬프 쿼리를 붙인다. */
async function fetchGitHubData(){
  const resp=await fetch(GITHUB_DATA_URL+'?t='+Date.now(),{cache:'no-store'});
  if(!resp.ok) throw new Error(`GitHub 데이터 요청 실패 (HTTP ${resp.status}) — data.json 경로/공개여부 확인 필요`);
  const json=await resp.json();
  if(!json||!json.sheets) throw new Error('data.json 형식 오류 (sheets 필드 없음)');
  return json;
}
/* 추가 SKU 카드/채널 설정 전용 파일(usercards.json) — data.json과 분리된 별도 파일이라 따로 받는다.
   아직 카드를 한 번도 추가한 적 없으면(/api/cards가 한 번도 성공한 적 없으면) 파일 자체가
   존재하지 않을 수 있으므로, 404는 에러가 아니라 "아직 비어있음"으로 취급한다. */
async function fetchUserCardsData(){
  const resp=await fetch(GITHUB_USERCARDS_URL+'?t='+Date.now(),{cache:'no-store'});
  if(resp.status===404) return {userCards:[],channelPrefs:[]};
  if(!resp.ok) throw new Error(`usercards.json 요청 실패 (HTTP ${resp.status})`);
  const json=await resp.json();
  return {userCards:Array.isArray(json.userCards)?json.userCards:[], channelPrefs:Array.isArray(json.channelPrefs)?json.channelPrefs:[]};
}
/* GitHub data.json의 sheets.xxx는 이미 2차원 배열(행×셀)이라 그대로 반환한다.
   각 셀은 Apps Script에서 {v, f} 형태로 만들어 보내므로 ndate/nnum/nstr이 기존과 동일하게 동작한다. */
const cellsOf=arr=>Array.isArray(arr)?arr:[];
function nnum(c){if(!c)return 0;if(typeof c.v==='number')return c.v;return num(c.f!=null?c.f:c.v);}
function ndate(c){if(!c)return '';let d=normDate(c.v);if(d)return d;return normDate(c.f);}
function nstr(c){if(!c)return '';const x=(c.v!=null?c.v:(c.f!=null?c.f:''));return String(x).trim();}
function buildLive(s26,s25,pr,sk,otherRows){
  const raw26=cellsOf(s26).length, raw25=cellsOf(s25).length, rawPromo=cellsOf(pr).length;
  console.log(`[data.json 원본 행수] 26년 매출:${raw26} · 25년 매출:${raw25} · 프로모션_항목:${rawPromo}`);
  /* '26_제품 일자별' 시트는 컬럼이 종종 추가/이동된다(예: SKU 시트에서 이미 겪은 주문건수 신설로 인한 컬럼 밀림).
     고정 인덱스(r[1]=날짜, r[2]=매출 …)만 믿지 않고, 먼저 헤더 행에서 실제 컬럼 위치를 찾아보고,
     헤더를 못 찾을 때만 기존 고정 인덱스로 폴백한다 — 시트 구조가 바뀌어도 자동으로 다시 맞춰진다. */
  function deriveShopCols26(rows){
    const hdrTxt=c=>c?String(c.f!=null?c.f:(c.v!=null?c.v:'')).replace(/\s/g,''):'';
    let hdr=null,hrow=-1;
    for(let r=0;r<Math.min(rows.length,15);r++){
      const cells=(rows[r]||[]).map(hdrTxt);
      if(cells.some(t=>/날짜|일자|日付/.test(t)) && cells.some(t=>/매출|판매액|売上/.test(t))){hdr=cells;hrow=r;break;}
    }
    if(!hdr) return null;
    const find=kws=>{ for(let i=0;i<hdr.length;i++){ if(kws.some(k=>hdr[i].includes(k))) return i; } return -1; };
    const d=find(['날짜','일자','日付']), rev=find(['매출','판매액','売上']);
    if(d<0||rev<0||d===rev) return null;
    const ord=find(['주문건수','注文']), qty=find(['판매수량','수량','販売','個数','点数']),
          uv=find(['UV','방문']), nc=find(['신규','新規']), oc=find(['기존','既存']);
    // 같은 컬럼이 서로 다른 역할로 중복 매핑되면(예: 헤더 텍스트가 애매해 잘못 매칭된 경우) 이 매핑 전체를 폐기한다
    const idxs=[d,rev,ord,qty,uv,nc,oc].filter(i=>i>=0);
    if(new Set(idxs).size!==idxs.length) return null;
    // 헤더 텍스트만 믿지 않고, 실제 데이터 몇 행을 샘플링해 d열이 진짜 날짜로, rev열이 진짜 매출(양수 다수)로
    // 파싱되는지 검증한다 — 예) '등록일자'나 '순번' 같은 다른 컬럼이 키워드만 비슷해 잘못 걸리는 경우를 걸러낸다.
    const probe=rows.slice(hrow+1,hrow+1+20).filter(Boolean);
    if(probe.length>=5){
      const dOk=probe.filter(r=>ndate(r[d])).length;
      const revOk=probe.filter(r=>nnum(r[rev])>0).length;
      if(dOk/probe.length<0.6||revOk/probe.length<0.6) return null;
    }
    return {hrow, d, rev, ord, qty, uv, nc, oc};
  }
  const rows26=cellsOf(s26);
  const map26=deriveShopCols26(rows26);
  const shop=[];
  if(map26){
    console.log(`[26년 매출] 헤더 자동인식 성공 (${map26.hrow}행) · d=${map26.d} rev=${map26.rev} ord=${map26.ord} qty=${map26.qty} uv=${map26.uv} nc=${map26.nc} oc=${map26.oc}`);
    // 진단용: 시트의 마지막 3개 행에 대해 실제 raw 셀 값과 ndate/nnum 파싱 결과를 그대로 콘솔에 남긴다.
    // "마지막 날짜가 누락된다"는 증상은 위치가 아니라 그 행의 실제 셀 값이 원인이므로, 값 자체를 눈으로 확인하기 위함.
    rows26.slice(-3).forEach((r,i)=>{
      const rawD=r[map26.d], rawRev=r[map26.rev];
      console.log(`[26년 매출 · 끝에서 ${rows26.slice(-3).length-i}번째 행] `+
        `d열 raw=${JSON.stringify(rawD)} → ndate="${ndate(rawD)}" · `+
        `rev열 raw=${JSON.stringify(rawRev)} → nnum=${nnum(rawRev)}`);
    });
    rows26.slice(map26.hrow+1).forEach(r=>{const d=ndate(r[map26.d]);const rev=nnum(r[map26.rev]);if(!d||rev<=0)return;
      shop.push({d,rev,ord:map26.ord>=0?nnum(r[map26.ord]):0,qty:map26.qty>=0?nnum(r[map26.qty]):0,uv:map26.uv>=0?nnum(r[map26.uv]):0,nc:map26.nc>=0?nnum(r[map26.nc]):0,oc:map26.oc>=0?nnum(r[map26.oc]):0});});
  } else {
    console.warn('[26년 매출] 헤더 자동인식 실패 → 기존 고정 컬럼(B=날짜,C=매출…)으로 폴백');
    rows26.slice(-3).forEach((r,i)=>{
      console.log(`[26년 매출(폴백) · 끝에서 ${rows26.slice(-3).length-i}번째 행] `+
        `B열 raw=${JSON.stringify(r[1])} → ndate="${ndate(r[1])}" · `+
        `C열 raw=${JSON.stringify(r[2])} → nnum=${nnum(r[2])}`);
    });
    rows26.forEach(r=>{const d=ndate(r[1]);const rev=nnum(r[2]);if(!d||rev<=0)return;shop.push({d,rev,ord:nnum(r[3]),qty:nnum(r[4]),uv:nnum(r[5]),nc:nnum(r[7]),oc:nnum(r[8])});});
  }
  cellsOf(s25).forEach(r=>{const d=ndate(r[0]);const rev=nnum(r[1]);if(!d||rev<=0)return;shop.push({d,rev,ord:nnum(r[3]),qty:nnum(r[4]),uv:nnum(r[5]),nc:0,oc:0});});
  /* 동일 일자가 두 번 이상 생성되는 경우(예: 26년/25년 시트가 같은 날짜를 중복 포함하거나,
     컬럼 오인식으로 같은 행이 두 갈래로 파싱된 경우)를 방지하는 안전장치.
     같은 날짜가 여러 번 나오면 합산해 하나로 병합하고, 몇 건이 병합됐는지 로그로 남긴다. */
  function dedupByDate(rows,fields){
    const map=new Map();let dupCount=0;
    rows.forEach(r=>{
      if(map.has(r.d)){dupCount++;const a=map.get(r.d);fields.forEach(f=>a[f]+=r[f]);}
      else map.set(r.d,{...r});
    });
    if(dupCount>0) console.warn(`[중복 일자 병합] ${dupCount}건의 중복 일자를 합산 병합함`);
    return [...map.values()].sort((a,b)=>a.d.localeCompare(b.d));
  }
  const shopDeduped=dedupByDate(shop,['rev','ord','qty','uv','nc','oc']);
  shop.length=0; shop.push(...shopDeduped);
  const sku={};
  /* SKU 시트 파싱 — 컬럼 자동 적합(auto-fit).
     주문건수 신설로 1블록이 1칸 늘면 그 뒤의 2번째 연도블록(K~S)도 통째로 1칸 밀린다.
     고정 인덱스 추측 대신, 여러 후보 매핑을 모두 시도해 '유효 행이 가장 많이 나오는' 매핑을 채택한다. */
  const hdrTxt=c=>c?String(c.f!=null?c.f:(c.v!=null?c.v:'')).replace(/\s/g,''):'';
  function deriveBlocks(rows){
    let hdr=null,hrow=-1;
    for(let r=0;r<Math.min(rows.length,15);r++){const cells=(rows[r]||[]).map(hdrTxt);if(cells.some(t=>/판매액|売上/.test(t))){hdr=cells;hrow=r;break;}}
    const probeStart=hrow>=0?hrow+1:0, probe=rows.slice(probeStart,probeStart+12);
    const dateScore=i=>probe.reduce((n,r)=>n+(r&&ndate(r[i])?1:0),0);
    if(!hdr)return null;
    const revs=[];let f=0,x;const find=from=>{for(let i=from;i<hdr.length;i++)if(/판매액|売上/.test(hdr[i]))return i;return -1;};while((x=find(f))>=0){revs.push(x);f=x+1;}
    if(!revs.length)return null;
    const colName=(rv,kw)=>{for(let i=rv;i<hdr.length;i++){if(kw.some(k=>hdr[i].includes(k)))return i;}return -1;};
    const pick=(rv,kw,off)=>{const c=colName(rv,kw);return c>=0?c:rv+off;};
    return revs.map(rv=>{let dc=-1,best=0;for(let i=rv-1;i>=Math.max(0,rv-5);i--){const s=dateScore(i);if(s>best){best=s;dc=i;}}if(dc<0)dc=Math.max(0,rv-2);
      return{d:dc,rev:rv,ord:pick(rv,['주문건수','注文'],1),qty:pick(rv,['판매수량','販売','個数','点数'],2),pv:pick(rv,['PV','アクセス'],3),uv:pick(rv,['UV','訪問'],4),nc:pick(rv,['신규','新規'],6),oc:pick(rv,['기존','既存'],7)};})
      .filter(b=>{const idxs=[b.d,b.rev,b.ord,b.qty,b.pv,b.uv,b.nc,b.oc].filter(i=>i>=0);return new Set(idxs).size===idxs.length;});
  }
  function parseSku(rows,blocks){const out=[];rows.forEach(r=>blocks.forEach(b=>{const d=ndate(r[b.d]);if(!d)return;
    const rev=nnum(r[b.rev]),ord=b.ord>=0?nnum(r[b.ord]):0,qty=b.qty>=0?nnum(r[b.qty]):0,uv=b.uv>=0?nnum(r[b.uv]):0;
    if(rev>0||uv>0||qty>0||ord>0)out.push({d,rev,ord,qty,pv:b.pv>=0?nnum(r[b.pv]):0,uv,nc:b.nc>=0?nnum(r[b.nc]):0,oc:b.oc>=0?nnum(r[b.oc]):0});}));
    return out;}
  // 후보 매핑들 (주문건수 = 판매액 직후 신설 기준)
  const CAND_NEW2=[{d:0,rev:2,ord:3,qty:4,pv:5,uv:6,nc:8,oc:9},{d:11,rev:13,ord:14,qty:15,pv:16,uv:17,nc:19,oc:20}]; // 2블록 모두 +1, 사이 gap 1칸
  const CAND_NEW1=[{d:0,rev:2,ord:3,qty:4,pv:5,uv:6,nc:8,oc:9},{d:10,rev:12,ord:13,qty:14,pv:15,uv:16,nc:18,oc:19}]; // 1블록만 +1
  const CAND_OLD =[{d:0,rev:2,ord:-1,qty:3,pv:4,uv:5,nc:7,oc:8},{d:10,rev:12,ord:-1,qty:13,pv:14,uv:15,nc:17,oc:18}]; // 주문건수 이전 구조
  Object.keys(sk).forEach(key=>{
    const rows=cellsOf(sk[key]);
    const cands=[['헤더자동',deriveBlocks(rows)],['신규(2블록시프트)',CAND_NEW2],['신규(1블록시프트)',CAND_NEW1],['구버전',CAND_OLD]].filter(c=>c[1]);
    let best=null;
    cands.forEach(([nm,bl])=>{const out=parseSku(rows,bl);console.log(`[SKU:${key}] 후보 '${nm}': ${out.length}행`+(out.length?` · 예시 ${JSON.stringify(out[0])}`:''));if(!best||out.length>best.out.length)best={nm,bl,out};});
    if(best){console.log(`[SKU:${key}] ✅ 채택='${best.nm}' (${best.out.length}행) · 매핑=${JSON.stringify(best.bl)}`);sku[key]=dedupByDate(best.out,['rev','ord','qty','pv','uv','nc','oc']);}
    else{console.warn(`[SKU:${key}] ⚠ 인식 실패 — 행 0, 시트 구조 확인 필요`);sku[key]=[];}
  });

  /* 그외 SKU(v2) — '그외상품' 시트: 오프셋 블록이 아닌 단일 평면 테이블.
     컬럼 순서: 프로모션명(0)/일자(1)/상품번호(2)/상품명(3)/매출(4)/주문건수(5)/판매수량(6)/PV(7)/UV(8)/전환율(9,미사용)/신규구매건수(10)/리피트구매건수(11).
     기존 '그외' 시트(연도별 오프셋 두 블록, 프로모션명 컬럼 없음)를 대체한다. 프로모션명이 행마다 명시돼 있어
     ③탭 "추가 SKU 카드" 기능이 날짜범위 추정 없이 (프로모션명,상품번호)로 바로 매칭할 수 있다 — 그래서 아래
     평면 배열(otherSkuRows)을 return에도 그대로 실어 보낸다. 기존 4개 고정 SKU와 같은 sku{} 객체에는
     지금처럼 합류시켜, skuRange/skuSum/skuConv/computeAgg 등 기존 계산 함수를 그대로 재사용한다. */
  const otherSkuNames={};
  const otherSkuRows=[];
  {
    const reserved=['shop', ...Object.keys(sk).map(k=>k.toLowerCase())];
    const byCode={};
    cellsOf(otherRows).forEach(r=>{
      const promo=nstr(r[0]); if(!promo||promo==='프로모션명') return;
      const d=ndate(r[1]); const code=nstr(r[2]).trim(); const name=nstr(r[3]).trim();
      if(!d||!code) return;
      const rev=nnum(r[4]),ord=nnum(r[5]),qty=nnum(r[6]),pv=nnum(r[7]),uv=nnum(r[8]),nc=nnum(r[10]),oc=nnum(r[11]);
      if(!(rev>0||uv>0||qty>0||ord>0)) return;
      otherSkuRows.push({promo,d,code,name,rev,ord,qty,pv,uv,nc,oc});
      if(reserved.indexOf(code.toLowerCase())>=0) return;
      (byCode[code]=byCode[code]||[]).push({d,rev,ord,qty,pv,uv,nc,oc});
      if(name && (!otherSkuNames[code]||d>=otherSkuNames[code].d)) otherSkuNames[code]={name,d};
    });
    Object.keys(byCode).forEach(code=>{ sku[code]=dedupByDate(byCode[code],['rev','ord','qty','pv','uv','nc','oc']); });
  }
  const otherSkuNameMap={}; Object.keys(otherSkuNames).forEach(c=>{otherSkuNameMap[c]=otherSkuNames[c].name;});

  const promos=[];cellsOf(pr).forEach(r=>{const nm=nstr(r[0]);if(!nm||nm==='프로모션명')return;const st=ndate(r[5]);if(!st)return;const yy=String(Math.round(nnum(r[1]))).slice(-2);const mm=String(Math.round(nnum(r[2])));
    const prevStart=ndate(r[7]),prevEnd=ndate(r[8]),yoyStart=ndate(r[9]),yoyEnd=ndate(r[10]);
    const o={id:`${yy}-${mm}-${nm}`,label:`${yy}년 ${mm}월 ${nm}`,type:nm,year:yy,start:st,end:ndate(r[6])||st};
    if(prevStart){o.prevStart=prevStart;o.prevEnd=prevEnd||prevStart;}
    if(yoyStart){o.yoyStart=yoyStart;o.yoyEnd=yoyEnd||yoyStart;}
    promos.push(o);});
  derivePrevYoy(promos);
  if(!shop.length) throw new Error(`숍 매출 파싱 결과 0행 (원본 26년 ${raw26}행/25년 ${raw25}행 — 날짜·매출 컬럼 위치(B/C열, A/B열) 확인 필요)`);
  if(!promos.length) throw new Error(`프로모션 파싱 결과 0행 (원본 프로모션_항목 ${rawPromo}행 — A열 프로모션명/F열 시작일 컬럼 위치 확인 필요)`);
  if(shop.length<30) throw new Error(`숍 매출 파싱 ${shop.length}행뿐 (원본 26년 ${raw26}행/25년 ${raw25}행 — 시트 구조 변경 여부 확인 필요)`);
  return{shop,sku,promos,skuKeys:['yp0001','yp3755','ybox_2508','ys0211'],otherSkuNames:otherSkuNameMap,otherSkuRows};
}
async function loadLive(){
  setStatus('load');
  try{
    const json=await fetchGitHubData();
    const sh=json.sheets||{};
    const got={
      shop26:sh.shop26||[], shop25:sh.shop25||[], promo:sh.promo||[],
      yp0001:sh.yp0001||[], yp3755:sh.yp3755||[], ybox_2508:sh.ybox_2508||[], ys0211:sh.ys0211||[],
      otherSkuV2:sh.otherSkuV2||[],
    };
    // 핵심 시트(숍)가 둘 다 비어있으면 실시간 갱신 불가 → 스냅샷 유지
    if(!got.shop26.length&&!got.shop25.length){
      throw new Error('숍 매출 데이터가 비어 있음 (data.json의 shop26/shop25 확인 필요 — Apps Script가 정상 실행됐는지 점검)');
    }
    if(!got.promo.length){
      console.warn('[프로모션 데이터 없음] 스냅샷 프로모션 목록 유지');
    }
    const _prevSku=(DATA&&DATA.sku)||{};
    const _prevOtherSkuNames=(DATA&&DATA.otherSkuNames)||{};
    const _live=buildLive(got.shop26,got.shop25,got.promo,{yp0001:got.yp0001,yp3755:got.yp3755,ybox_2508:got.ybox_2508,ys0211:got.ys0211},got.otherSkuV2);
    // 고정 4개 SKU뿐 아니라 그외(동적) SKU도 동일하게 보호: 이번 라운드에 특정 코드가 0행이면
    // (일시적 시트 파싱 문제 등) 직전에 로드했던 데이터를 유지한다.
    Object.keys(_prevSku).forEach(k=>{
      if((!_live.sku[k]||!_live.sku[k].length)&&_prevSku[k]&&_prevSku[k].length){
        console.warn(`[SKU:${k}] 이번 데이터 0행 → 이전 데이터 유지(${_prevSku[k].length}행)`);
        _live.sku[k]=_prevSku[k];
      }
    });
    const _prevTraffic=DATA.traffic;
    const _prevAffiliate=DATA.affiliate;
    const _prevCoupon=DATA.coupon;
    DATA=_live;
    if(_prevTraffic) DATA.traffic=_prevTraffic;
    if(_prevAffiliate) DATA.affiliate=_prevAffiliate;
    if(_prevCoupon) DATA.coupon=_prevCoupon;
    DATA.otherSkuNames=Object.assign({}, _prevOtherSkuNames, DATA.otherSkuNames||{});
    DATA.otherSkuRows=_live.otherSkuRows||[];
    // 추가 SKU 카드 / 채널 설정: usercards.json(별도 파일, /api/cards가 직접 커밋)이 최신 소스지만,
    // 이 브라우저에서 방금 추가/삭제한 항목은 GitHub 커밋의 raw CDN 반영(보통 수 초~수십 초) 전까지
    // 사라지지 않도록 mergeUserCards()로 낙관적으로 유지한다. 이 파일 하나가 실패해도(예: 아직 한 번도
    // 생성된 적 없어 404) 매출 데이터 로드 자체는 끊기지 않도록 별도 try/catch로 감싼다.
    try{
      const uc=await fetchUserCardsData();
      DATA.userCards=mergeUserCards(uc.userCards, DATA.userCards||[]);
      DATA.channelPrefs=uc.channelPrefs.length?uc.channelPrefs:(DATA.channelPrefs||[]);
      if(!DATA.channelPrefs.length){
        seedDefaultChannelsIfNeeded().catch(e=>console.warn('[대시보드] 채널 기본값 자동 등록 실패:', e.message));
      }
    }catch(e){
      console.warn('[대시보드] usercards.json 로드 실패 — 이전 상태 유지:', e.message);
    }
    DATA.promos=mergePromos(SNAPSHOT_PROMOS,DATA.promos);
    derivePrevYoy(DATA.promos);
    // 월 목표매출: data.json의 monthlyGoals(Apps Script가 프로모션_항목 N:P열에서 추출)를 우선 사용하고,
    // 아직 재배포 전이라 비어있으면 원본 promo 시트 행에서 N:P열을 직접 파싱해 대체한다.
    DATA.monthlyGoals=(Array.isArray(json.monthlyGoals)&&json.monthlyGoals.length)?json.monthlyGoals:parsePromoGoals_(got.promo);
    console.log('[대시보드] GitHub 데이터 로드 완료 · 프로모션 '+DATA.promos.length+'개 · 생성시각 '+(json.generatedAt||'-'));
    console.table(DATA.promos.map(p=>({id:p.id,label:p.label,start:p.start,end:p.end})));
    initControls();
    setStatus('live', json.generatedAt?('GitHub 갱신 '+json.generatedAt.replace('T',' ').slice(0,16)):undefined);
    renderAll();
  }catch(e){console.error('[대시보드] GitHub 데이터 로드 실패 → 스냅샷 유지:',e.message);setStatus('snap',e.message);}
}

/* ============================================================
   신규 기능: 탭 ⑥ 유입 분석 (기존 코드/DATA/탭·함수는 전혀 수정하지 않고 전부 새로 추가)
   데이터 출처: data.json의 traffic 네임스페이스 (Apps Script가 프로모션별로 누적)
   traffic = { promos:[[cells]], shop:{promoId:cells},
               sku:{yp0001:{promoId:cells},yp3755:{...},ys0211:{...},ybox2508:{...}},
               other:{promoId:cells} }
   ============================================================ */

if(!DATA.traffic) DATA.traffic={promos:[], shop:{}, sku:{yp0001:{},yp3755:{},ys0211:{},ybox2508:{}}, other:{}, dynamicSkuCodes:[]};
if(!DATA.monthlyGoals) DATA.monthlyGoals=[];
// 신규: 추가 SKU 카드 / 채널 설정 / 그외상품 평면 데이터 — 스냅샷(내장) 데이터에는 없는 필드이므로,
// loadLive() 이전(스냅샷으로 첫 렌더링하는 시점)에도 undefined 참조로 죽지 않도록 기본값을 깔아둔다.
if(!DATA.userCards) DATA.userCards=[];
if(!DATA.channelPrefs) DATA.channelPrefs=[];
if(!DATA.otherSkuRows) DATA.otherSkuRows=[];

/* ============================================================
 * 신규: 대시보드 "쓰기" 경로 — 추가 SKU 카드 / 채널 설정
 * 같은 Vercel 프로젝트의 서버리스 함수(/api/cards, api/cards.js)를 호출한다. 같은 오리진이라
 * CORS/인증 문제가 전혀 없다(Apps Script 웹 앱을 직접 호출하던 이전 방식은 회사 보안 정책상
 * "모든 사용자" 배포가 불가능해 포기 — api/cards.js 상단 주석 참고). 성공하면 DATA를 낙관적으로
 * 갱신해, GitHub 커밋의 raw CDN 반영을 기다리지 않고 화면에 바로 반영한다.
 * ============================================================ */
async function postDashboardAction(action,payload){
  const resp=await fetch(DASHBOARD_WRITE_API,{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({action,payload}),
  });
  const json=await resp.json();
  if(!json.ok) throw new Error(json.error||'저장에 실패했습니다.');
  return json;
}
async function addSkuCard(card){ // card:{title,cur:{promoId,code},prev?,yoy?}
  const r=await postDashboardAction('addCard',card);
  DATA.userCards.push(Object.assign({id:r.id,pinned:false,createdAt:new Date().toISOString()},card));
  return r.id;
}
async function pinSkuCard(id,pinned){
  await postDashboardAction('pinCard',{id,pinned});
  const c=DATA.userCards.find(x=>x.id===id); if(c) c.pinned=pinned;
}
async function deleteSkuCardPermanently(id){
  await postDashboardAction('deleteCard',{id});
  const c=DATA.userCards.find(x=>x.id===id); if(c) c._locallyDeleted=true;
  DATA.userCards=DATA.userCards.filter(x=>x.id!==id);
}
async function addChannelPref(category,channelName){
  const r=await postDashboardAction('addChannel',{category,channelName});
  DATA.channelPrefs.push({id:r.id,category,channelName,order:DATA.channelPrefs.length,createdAt:new Date().toISOString()});
  return r.id;
}
async function removeChannelPref(id){
  await postDashboardAction('removeChannel',{id});
  DATA.channelPrefs=DATA.channelPrefs.filter(x=>x.id!==id);
}
/* 채널 체크리스트를 한 번도 설정하지 않은 상태(=channelPrefs가 비어있음)에서 매번 수동으로
   채널을 추가해야 하는 번거로움을 없애기 위해, 최초 1회 기본 채널 세트를 서버에 자동 등록한다.
   서버(api/cards.js)가 store.channelsSeeded 플래그로 딱 한 번만 실제 커밋하도록 멱등 처리하므로,
   사용자가 나중에 전체 채널을 의도적으로 지워도 재시딩되지 않는다(add/remove 자유도는 그대로 유지). */
async function seedDefaultChannelsIfNeeded(){
  const r=await postDashboardAction('seedDefaultChannels',{});
  if(r.seeded && Array.isArray(r.channels) && r.channels.length){
    r.channels.forEach(c=>DATA.channelPrefs.push(c));
    renderF();
  }
}

const TRAFFIC_KEYS=['shop','yp0001','yp3755','ys0211','ybox2508'];
const TRAFFIC_INT_CATS=['店舗商品ページ','楽天市場トップ','店舗トップ','楽天サーチ','ランキング市場','買い物かご','お気に入り'];
const TRAFFIC_EXT_CATS=['Google','www.tiktok.com','Instagram','Youtube','Facebook'];
const TRAFFIC_EXT_LABEL={'www.tiktok.com':'TikTok','Youtube':'YouTube'};
const trafficCatLabel=c=>TRAFFIC_EXT_LABEL[c]||c;
/* 컬럼 순서: 금번/직전/전년/직전차/직전비/전년차/전년비 (값 3개 먼저, 그다음 델타 4개 — ③⑥탭 공통) */
const TRAFFIC_TABLE_HEAD='<thead><tr><th>구분</th><th class="gdiv">금번</th><th>직전</th><th>전년</th><th>직전차</th><th>직전비</th><th>전년차</th><th>전년비</th></tr></thead>';
const TRAFFIC_DAILY_HEAD='<thead><tr><th>날짜</th><th class="gdiv">금번</th><th>직전</th><th>전년</th><th>직전차</th><th>직전비</th><th>전년차</th><th>전년비</th></tr></thead>';
/* 한 지표(그룹) 하나에 대한 7개 <td> — 금번/직전/전년/직전차/직전비/전년차/전년비.
   ratio=true(비중·전환율 등)면 "차"에 %p 절대차이(deltaP)를, false(매출·수량 등)면 값 자체의
   절대차이(diffAbsTraffic)를 쓴다. "비"(상대변화율)는 두 경우 모두 delta()로 동일 —
   기존 trafficRowHTML/trafficShareRowHTML이 쓰던 규칙 그대로다. */
function cmp7TDs(curV,prevV,yoyV,fmt,ratio){
  fmt=fmt||f0;
  const dP=ratio?deltaP(curV,prevV):diffAbsTraffic(curV,prevV);
  const rP=delta(curV,prevV);
  const dY=ratio?deltaP(curV,yoyV):diffAbsTraffic(curV,yoyV);
  const rY=delta(curV,yoyV);
  const v=x=>x==null?'—':fmt(x);
  return `<td class="gdiv">${v(curV)}</td><td>${v(prevV)}</td><td>${v(yoyV)}</td>`+
    `<td class="${dP.c}">${dP.t}</td><td class="${rP.c}">${rP.t}</td>`+
    `<td class="${dY.c}">${dY.t}</td><td class="${rY.c}">${rY.t}</td>`;
}
function cmp7Row(label,curV,prevV,yoyV,fmt,ratio){
  return `<tr><td>${label}</td>${cmp7TDs(curV,prevV,yoyV,fmt,ratio)}</tr>`;
}
const TRAFFIC_COLORS=['#378ADD','#1D9E75','#D85A30','#7F77DD','#BA7517','#3AAFA9','#C2185B','#6D4C41'];

let trafficState={promoId:null, target:'shop', date:'__ALL__'};
let trafficParsedCache={};
let _trafficAggCache=null;
let trafficChanExpand={int:{}, ext:{}};

/* ---- 프로모션_항목 파싱 — 기존 buildLive 내부 promo 파싱과 동일한 컬럼 규칙을 별도 함수로 재사용(기존 함수 미변경) ---- */
function parseTrafficPromos(cells){
  const promos=[];
  cellsOf(cells).forEach(r=>{
    const nm=nstr(r[0]); if(!nm||nm==='프로모션명') return;
    const st=ndate(r[5]); if(!st) return;
    const yy=String(Math.round(nnum(r[1]))).slice(-2);
    const mm=String(Math.round(nnum(r[2])));
    const prevStart=ndate(r[7]),prevEnd=ndate(r[8]),yoyStart=ndate(r[9]),yoyEnd=ndate(r[10]);
    const o={id:`${yy}-${mm}-${nm}`,label:`${yy}년 ${mm}월 ${nm}`,type:nm,year:yy,start:st,end:ndate(r[6])||st};
    if(prevStart){o.prevStart=prevStart;o.prevEnd=prevEnd||prevStart;}
    if(yoyStart){o.yoyStart=yoyStart;o.yoyEnd=yoyEnd||yoyStart;}
    promos.push(o);
  });
  derivePrevYoy(promos);
  return promos;
}
const trafficPromoById=id=>DATA.traffic.promos.find(p=>p.id===id);
const trafficPromosSorted=()=>DATA.traffic.promos.slice().sort((a,b)=>b.start.localeCompare(a.start));
const trafficPromoLabelShort=id=>{const q=trafficPromoById(id);return q?shortLabel(q):'';};
function hasTrafficData(target,promoId){
  if(!promoId) return false;
  const store = target==='shop'?DATA.traffic.shop:(target==='other'?DATA.traffic.other:(DATA.traffic.sku||{})[target]);
  return !!(store && store[promoId] && store[promoId].length);
}

/* ---- 내부/외부 판정은 반드시 エリア1 값 기준. 참조원명(参照元)은 상세 채널(12종) 집계에만 사용 ---- */
function classifyArea(a1){ return a1==='楽天市場内'?'내부':(a1==='楽天市場外'?'외부':null); }

function newTrafficAcc(){ return {total:0, internal:0, external:0, byCat:{}, byCatExt:{}, otherInt:0, otherExt:0, unclassified:0, _refTotals:{}, _refArea:{}}; }
function addTrafficRow(acc,row){
  acc.total+=row.val;
  acc._refTotals[row.ref]=(acc._refTotals[row.ref]||0)+row.val;
  acc._refArea[row.ref]=row.area;
  if(row.area==='내부'){
    acc.internal+=row.val;
    if(TRAFFIC_INT_CATS.includes(row.ref)) acc.byCat[row.ref]=(acc.byCat[row.ref]||0)+row.val;
    else acc.otherInt+=row.val;
  } else if(row.area==='외부'){
    acc.external+=row.val;
    if(TRAFFIC_EXT_CATS.includes(row.ref)){ const lbl=trafficCatLabel(row.ref); acc.byCatExt[lbl]=(acc.byCatExt[lbl]||0)+row.val; }
    else acc.otherExt+=row.val;
  }
}
function finalizeTrafficAcc(acc, totalOverride){
  if(totalOverride!=null){ acc.unclassified=Math.max(0,totalOverride-(acc.internal+acc.external)); acc.total=totalOverride; }
  const entries=Object.keys(acc._refTotals).map(ref=>({ref, val:acc._refTotals[ref], area:acc._refArea[ref]}));
  acc.top=entries.slice().sort((a,b)=>b.val-a.val).slice(0,30)
    .map((o,i)=>({rank:i+1, ref:o.ref, val:o.val, area:o.area, share: acc.total? o.val/acc.total:0}));
  acc.otherIntList=entries.filter(e=>e.area==='내부' && !TRAFFIC_INT_CATS.includes(e.ref)).sort((a,b)=>b.val-a.val);
  acc.otherExtList=entries.filter(e=>e.area==='외부' && !TRAFFIC_EXT_CATS.includes(e.ref)).sort((a,b)=>b.val-a.val);
  // _refTotals/_refArea는 예전에는 여기서 지웠지만(top/otherIntList로 충분했으므로), ⑥탭의
  // 사용자 채널 체크리스트(trackedChannels)가 Top30에 없는 채널이라도 실제 유입수를 조회할 수
  // 있어야 해서 그대로 남겨둔다 — 정적 페이지 렌더링용 객체라 메모리에 계속 남아있어도 무해하다.
  return acc;
}
function groupTrafficByDate(rows, totalOverrideByDate){
  const byDate={};
  rows.forEach(row=>{ (byDate[row.d]=byDate[row.d]||newTrafficAcc()); addTrafficRow(byDate[row.d], row); });
  Object.keys(byDate).forEach(d=>finalizeTrafficAcc(byDate[d], totalOverrideByDate?totalOverrideByDate[d]:null));
  return byDate;
}
function aggTrafficAll(rows, totalOverrideSum){
  const acc=newTrafficAcc(); rows.forEach(row=>addTrafficRow(acc,row)); return finalizeTrafficAcc(acc, totalOverrideSum!=null?totalOverrideSum:null);
}

/* ---- SKU/그외 RAW 파서 (RMS Excel 다운로드 포맷, 금번/직전/전년 3블록) — エリア1 컬럼을 그대로 사용, 참조원 문자열 매칭 없음 ---- */
function deriveTrafficBlocks(rows){
  let hdr=null,hrow=-1;
  for(let r=0;r<Math.min(rows.length,10);r++){
    const cells=(rows[r]||[]).map(nstr);
    if(cells.includes('日付') && cells.some(t=>t.indexOf('ユニークユーザー')>=0)){ hdr=cells; hrow=r; break; }
  }
  if(!hdr) return null;
  const dateCols=[]; hdr.forEach((t,i)=>{ if(t==='日付') dateCols.push(i); });
  if(!dateCols.length) return null;
  const periods=['cur','prev','yoy'];
  return {hrow, blocks:dateCols.slice(0,3).map((d,i)=>({period:periods[i], d, ref:d+1, area1:d+2, area2:d+3, access:d+4, share:d+5, uv:d+6}))};
}
function parseTrafficLong(rows, map){
  const out={cur:[],prev:[],yoy:[]};
  if(!map) return out;
  rows.slice(map.hrow+1).forEach(r=>{
    map.blocks.forEach(b=>{
      const d=ndate(r[b.d]); if(!d) return;
      const ref=nstr(r[b.ref]); if(!ref) return;
      const area=classifyArea(nstr(r[b.area1]));
      const uv=nnum(r[b.uv]);
      out[b.period].push({d, ref, area, val:uv});
    });
  });
  return out;
}

/* ---- SHOP 전용 파서 (RMS 화면 복사 포맷) — A/B열 범례에서 참조원별 エリア1 값을 얻어 그대로 사용 ---- */
function parseShopLegend(rows){
  const legend={};
  rows.forEach(r=>{
    const name=nstr(r[0]); const area=nstr(r[1]);
    if(name && (area==='楽天市場内'||area==='楽天市場外')) legend[name]=classifyArea(area);
  });
  return legend;
}
function parseDotDate(s){
  const m=String(s||'').trim().match(/^(\d{2})\.(\d{2})\.(\d{2})$/);
  return m? '20'+m[1]+'-'+m[2]+'-'+m[3] : '';
}
function findShopSections(rows){
  const sections=[]; const periodMap={'금번':'cur','직전':'prev','전년':'yoy'};
  for(let r=0;r<rows.length;r++){
    const row=rows[r]||[];
    for(let c=0;c<row.length;c++){
      const m=nstr(row[c]).match(/^(금번|직전|전년)\s*유입원/);
      if(m){
        const hdrRow=r+1, hdr=rows[hdrRow]||[], blocks=[];
        for(let cc=3;cc<hdr.length;cc+=4){ const d=parseDotDate(nstr(hdr[cc])); if(d) blocks.push({date:d, baseCol:cc}); }
        sections.push({period:periodMap[m[1]], dataStartRow:hdrRow+2, blocks});
        break;
      }
    }
  }
  return sections;
}
function extractShopSectionRows(rows, section, legend){
  const out=[]; const totalByDate={};
  /* 금번/직전/전년 섹션 사이에는 빈 행 구분자가 없고 바로 다음 섹션의 "OO 유입원" 제목 행이
     이어진다. 기존 종료 조건("rank/ref 둘 다 완전 공백")만으로는 이 제목 행을 지나쳐 다음
     섹션의 데이터(예: 직전 섹션의 全体·참조원 값)까지 같은 날짜로 계속 읽어 들이는 문제가
     있었다. findShopSections()가 섹션을 나눌 때 쓰는 것과 동일한 제목 패턴을 만나면 그
     행을 소비하기 전에 즉시 멈춘다 — 섹션 경계를 findShopSections()와 같은 기준으로 판정. */
  const SECTION_TITLE_RE=/^(금번|직전|전년)\s*유입원/;
  section.blocks.forEach(({date,baseCol})=>{
    let rr=section.dataStartRow, guard=0;
    while(rr<rows.length && guard<80){
      const row=rows[rr]||[];
      const rankCell=nstr(row[baseCol]), refCell=nstr(row[baseCol+1]);
      if(rankCell===''&&refCell===''){ break; }
      if(row.some(c=>SECTION_TITLE_RE.test(nstr(c)))){ break; }
      if(refCell==='全体'){ totalByDate[date]=nnum(row[baseCol+2]); rr++; guard++; continue; }
      if(refCell===''||refCell==='表示'){ rr++; guard++; continue; }
      out.push({d:date, ref:refCell, area:legend[refCell]||null, val:nnum(row[baseCol+2])});
      rr++; guard++;
    }
  });
  return {rows:out, totalByDate};
}

/* ---- 대상별 원본 RAW → 기간별(cur/prev/yoy) 행 배열 ---- */
function buildTrafficRawRows(target, promoId){
  if(target==='shop'){
    const raw=(DATA.traffic.shop||{})[promoId]; if(!raw) return null;
    const legend=parseShopLegend(raw);
    const sections=findShopSections(raw);
    const bucket={cur:{rows:[],totalByDate:{}},prev:{rows:[],totalByDate:{}},yoy:{rows:[],totalByDate:{}}};
    sections.forEach(sec=>{
      const {rows,totalByDate}=extractShopSectionRows(raw, sec, legend);
      bucket[sec.period].rows.push(...rows);
      Object.assign(bucket[sec.period].totalByDate, totalByDate);
    });
    return {curRows:bucket.cur.rows, prevRows:bucket.prev.rows, yoyRows:bucket.yoy.rows,
            curTotalByDate:bucket.cur.totalByDate, prevTotalByDate:bucket.prev.totalByDate, yoyTotalByDate:bucket.yoy.totalByDate};
  }
  const store = target==='other'?DATA.traffic.other:(DATA.traffic.sku||{})[target];
  const raw = store && store[promoId]; if(!raw) return null;
  const map=deriveTrafficBlocks(raw);
  const parsed=parseTrafficLong(raw, map);
  return {curRows:parsed.cur, prevRows:parsed.prev, yoyRows:parsed.yoy};
}

/* ---- 프로모션+대상 하나에 대한 전체 결과(요약·일별·Top30) 계산 — 경과일 기준으로 직전/전년 매칭(기존 computeAgg와 동일 철학) ---- */
function getTrafficAgg(target, promoId){
  if(!target||!promoId) return null;
  const cacheKey=target+':'+promoId;
  if(trafficParsedCache[cacheKey]) return trafficParsedCache[cacheKey];
  const built=buildTrafficRawRows(target, promoId);
  if(!built) return null;
  const p=trafficPromoById(promoId); if(!p) return null;

  const curByDate=groupTrafficByDate(built.curRows, built.curTotalByDate);
  const prevByDate=groupTrafficByDate(built.prevRows, built.prevTotalByDate);
  const yoyByDate=groupTrafficByDate(built.yoyRows, built.yoyTotalByDate);

  const curDates=Object.keys(curByDate).sort();
  const prevLen=periodLen(p.prevStart,p.prevEnd), yoyLen=periodLen(p.yoyStart,p.yoyEnd);
  const daily=curDates.map((d,k)=>{
    const prevD=(p.prevStart && k<prevLen)?addDays(p.prevStart,k):null;
    const yoyD=(p.yoyStart && k<yoyLen)?addDays(p.yoyStart,k):null;
    return { k, d, cur:curByDate[d],
      prev: prevD&&prevByDate[prevD]?prevByDate[prevD]:null,
      yoy: yoyD&&yoyByDate[yoyD]?yoyByDate[yoyD]:null };
  });
  const sumOverride=m=>m?Object.values(m).reduce((a,b)=>a+b,0):null;
  const periodTotals={
    cur: aggTrafficAll(built.curRows, sumOverride(built.curTotalByDate)),
    prev: built.prevRows.length? aggTrafficAll(built.prevRows, sumOverride(built.prevTotalByDate)) : null,
    yoy: built.yoyRows.length? aggTrafficAll(built.yoyRows, sumOverride(built.yoyTotalByDate)) : null,
  };
  const result={target, promoId, daily, periodTotals};
  trafficParsedCache[cacheKey]=result;
  return result;
}

/* ---- 프로모션 진행일차 배지: 진행 중이면 "현재 N일차 / 총 M일" 자동 표시 ---- */
function todayStr(){ return new Date().toISOString().slice(0,10); }
function promoDayBadge(p){
  if(!p||!p.start||!p.end) return '';
  const t=todayStr();
  if(t<p.start||t>p.end) return '';
  return `현재 ${daysDiff(t,p.start)+1}일차 / 총 ${promoLen(p)}일`;
}

/* ---- CSV 다운로드 (범용 유틸 — 이후 다른 표에도 그대로 재사용 가능한 확장 가능 구조) ---- */
function toTrafficCSV(headers, rows){
  const esc=v=>{ v=(v==null?'':String(v)); return /[",\n]/.test(v) ? '"'+v.replace(/"/g,'""')+'"' : v; };
  return [headers.map(esc).join(','), ...rows.map(r=>r.map(esc).join(','))].join('\r\n');
}
function downloadTrafficCSV(filename, headers, rows){
  const csv='﻿'+toTrafficCSV(headers, rows);
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a'); a.href=url; a.download=filename; document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
}

/* ---- 요약/일별 표 한 행 렌더 — 실제 구현은 cmp7Row(공유, ③⑥탭 공통)에 위임 ---- */
function diffAbsTraffic(cur,prev){ if(prev==null||!isFinite(prev)) return {t:'—',c:'dmut'}; const x=(cur||0)-prev; return {t:(x>=0?'+':'')+f0(x), c:x>=0?'pos':'neg'}; }
function trafficRowHTML(label, curV, prevV, yoyV, fmt){ return cmp7Row(label, curV, prevV, yoyV, fmt||f0, false); }
/* 비중(%) 행 — "차"는 %p 절대차(deltaP), "비"는 비중값 자체의 상대변화율(delta) — cmp7Row(ratio=true)와 동일 규칙 */
function trafficShareRowHTML(label, curShare, prevShare, yoyShare, fmt){ return cmp7Row(label, curShare, prevShare, yoyShare, fmt||fp0, true); }
/* 지표 하나(total/internal/external)의 일별(경과일) 비교 표 — 금번/직전/전년/직전차/직전비/전년차/전년비 */
function trafficDailyTableHTML(agg, valFn){
  let t=TRAFFIC_DAILY_HEAD+'<tbody>';
  agg.daily.forEach(x=>{
    const cur=valFn(x.cur), prev=x.prev?valFn(x.prev):null, yoy=x.yoy?valFn(x.yoy):null;
    const dpA=diffAbsTraffic(cur,prev), dyA=diffAbsTraffic(cur,yoy);
    const dp=delta(cur,prev), dy=delta(cur,yoy);
    const cls=x.d===trafficState.date?' class="total"':'';
    t+=`<tr${cls} data-date="${x.d}"><td class="datecell">${mdLabel(x.d)}(${x.k+1}일차)</td><td>${f0(cur)}</td><td>${prev!=null?f0(prev):'—'}</td><td>${yoy!=null?f0(yoy):'—'}</td>
      <td class="${dpA.c}">${dpA.t}</td><td class="${dp.c}">${dp.t}</td>
      <td class="${dyA.c}">${dyA.t}</td><td class="${dy.c}">${dy.t}</td></tr>`;
  });
  return t+'</tbody>';
}
function wireTrafficDailyClicks(id){
  const el=document.getElementById(id); if(!el) return;
  el.querySelectorAll('tbody tr[data-date]').forEach(tr=>tr.onclick=()=>{ trafficState.date=tr.dataset.date; renderF(); });
}
/* 채널별 일별 상세 표 — 날짜×채널 피벗, 셀은 금번 기간의 해당 날짜 유입수 하나만(비교값 없음).
   채널명(헤더)을 클릭하면 trafficChanExpand[groupKey][채널명]이 토글되어 아래 trafficChannelDetailHTML이
   해당 채널의 금번/직전/전년 비교 일별표를 펼쳐 보여준다. */
function trafficChannelDailyTableHTML(agg, cats, getVal, groupKey){
  let t='<thead><tr><th>날짜</th>'+cats.map(c=>{
    const open=trafficChanExpand[groupKey][c];
    return `<th><span class="trf-chan-toggle" data-group="${groupKey}" data-chan="${c}" style="cursor:pointer">${open?'▾':'▸'} ${trafficCatLabel(c)}</span></th>`;
  }).join('')+'</tr></thead><tbody>';
  agg.daily.forEach(x=>{
    const cls=x.d===trafficState.date?' class="total"':'';
    t+=`<tr${cls} data-date="${x.d}"><td class="datecell">${mdLabel(x.d)}(${x.k+1}일차)</td>`+cats.map(c=>`<td>${f0(getVal(x.cur,c))}</td>`).join('')+'</tr>';
  });
  return t+'</tbody>';
}
/* 펼쳐진 채널들의 상세 비교표(금번/직전/전년/직전차/직전비/전년차/전년비) — 피벗 표(<table>) 밖의 별도 컨테이너에 렌더링된다.
   기존 trafficDailyTableHTML(전체/내부/외부용)을 채널 단위 getVal로 그대로 재사용. */
function trafficChannelDetailHTML(agg, cats, getVal, groupKey){
  const openCats=cats.filter(c=>trafficChanExpand[groupKey][c]);
  if(!openCats.length) return '';
  return openCats.map(c=>`<div class="sec">${trafficCatLabel(c)} 일별 상세</div><div class="tbl-scroll"><table>${trafficDailyTableHTML(agg, a=>getVal(a,c))}</table></div>`).join('');
}
/* 차트 툴팁 공통 설정 — 항목은 값 내림차순 정렬(itemSort), 각 항목 텍스트는 금번→직전→전년 순으로 표기.
   mode:'index',intersect:false 는 기존 탭④ c-line 차트와 동일한 설정 — 포인트 정중앙이 아니어도
   같은 x축(날짜) 위 어디에 마우스를 올려도 툴팁이 뜨도록 한다. */
function trafficTooltipConfig(agg){
  return {
    mode:'index', intersect:false,
    itemSort:(a,b)=>b.parsed.y-a.parsed.y,
    callbacks:{
      label:(ctx)=>{
        const day=agg.daily[ctx.dataIndex]; if(!day) return ctx.dataset.label+': '+f0(ctx.parsed.y);
        const getVal=ctx.dataset._getVal;
        const prevV=(day.prev&&getVal)?getVal(day.prev):null, yoyV=(day.yoy&&getVal)?getVal(day.yoy):null;
        return `${ctx.dataset.label}: ${f0(ctx.parsed.y)} (직전 ${prevV!=null?f0(prevV):'—'} · 전년 ${yoyV!=null?f0(yoyV):'—'})`;
      }
    }
  };
}

/* ---- 대상 버튼 탭 — 고정 5개(숍전체/yp0001/yp3755/ybox2508/ys0211) + 사용자가 ③탭에서
   추가한 SKU 카드(DATA.userCards)에 쓰인 코드들을 "+추가상품" 버튼으로 이어붙인다.
   추가 SKU는 채널(유입) 데이터가 아직 없을 수 있으므로(그외_raw는 별도 파이프라인 —
   Code.gs 상단 주석 참고) hasTrafficData()로 있음/없음 상태를 판정해 버튼에 표시만 하고,
   버튼 자체는 항상 노출한다(사용자 확정 사항: 데이터 유무와 무관하게 항상 버튼 표시). */
function customTrafficCodes(){
  const set=new Set();
  (DATA.userCards||[]).forEach(c=>{
    if(c.cur) set.add(c.cur.code);
    if(c.prev) set.add(c.prev.code);
    if(c.yoy) set.add(c.yoy.code);
  });
  return [...set];
}
function renderTargetTabs(){
  const wrap=document.getElementById('f-target-tabs'); if(!wrap) return;
  const fixed=[['shop','숍전체'],['yp0001','yp0001'],['yp3755','yp3755'],['ybox2508','ybox2508'],['ys0211','ys0211']];
  const custom=customTrafficCodes();
  wrap.innerHTML=fixed.map(([v,l])=>`<button type="button" class="tab${trafficState.target===v?' active':''}" data-target="${v}">${l}</button>`).join('')+
    custom.map(code=>{
      const has=hasTrafficData(code, trafficState.promoId);
      return `<button type="button" class="tab${trafficState.target===code?' active':''}${has?'':' trf-nodata'}" data-target="${escHtml(code)}">${escHtml(skuCodeLabel(code))}${has?'':' ○'}</button>`;
    }).join('');
}
const TRAFFIC_FIXED_TARGETS=['shop','yp0001','yp3755','ybox2508','ys0211'];
function wireTargetTabs(){
  const wrap=document.getElementById('f-target-tabs'); if(!wrap||wrap.dataset.wired) return;
  wrap.dataset.wired='1';
  wrap.addEventListener('click',(e)=>{
    const btn=e.target.closest('button[data-target]'); if(!btn) return;
    trafficState.target=btn.dataset.target;
    trafficState.date='__ALL__';
    // 고정 5개 대상에서는 기존 동작대로, 지금 프로모션에 데이터가 없으면 데이터가 있는 최근
    // 프로모션으로 자동 이동한다. 추가 SKU(사용자 지정 코드)는 아직 채널 데이터가 없는 경우가
    // 흔하므로(빈 상태 화면으로 명확히 안내하는 게 목적) 이 자동 이동을 적용하지 않는다.
    if(TRAFFIC_FIXED_TARGETS.includes(trafficState.target) && !hasTrafficData(trafficState.target, trafficState.promoId)){
      const withData=trafficPromosSorted().find(p=>hasTrafficData(trafficState.target,p.id));
      if(withData){
        trafficState.promoId=withData.id;
        const promoSel=document.getElementById('f-promo');
        if(promoSel) promoSel.value=withData.id;
      }
    }
    renderF();
  });
}
/* 채널 데이터가 아직 없는 추가 SKU를 선택했을 때의 안내 화면 — 빈 화면처럼 보이지 않게 상태를 명확히 설명한다. */
function renderTrafficEmptyState(code,promoLabel){
  return `<div class="trf-empty-state">
    <div class="trf-empty-icon">📭</div>
    <h4>이 상품의 채널 데이터가 아직 없습니다</h4>
    <p class="muted-note"><b>${escHtml(skuCodeLabel(code))}</b>은(는) <b>${escHtml(promoLabel)}</b> 기간에 대한 유입 채널 데이터가
      아직 수집되지 않았습니다.<br>그외_raw 시트 B2 셀에 상품번호 <code>${escHtml(code)}</code>를 입력하고
      해당 기간 RAW 데이터를 붙여넣으면, 다음 자동 동기화(최대 10분) 후 이 화면에 표시됩니다.</p>
    <span class="pill">상태: 채널 데이터 없음(미생성)</span>
  </div>`;
}
/* 고정 대상(숍전체/yp0001 등)인데도 이 프로모션에 유입 데이터가 아예 없는 드문 경우의 일반 안내 */
function renderTrafficGenericEmptyState(){
  return `<div class="trf-empty-state">
    <div class="trf-empty-icon">📭</div>
    <h4>유입 데이터가 없습니다</h4>
    <p class="muted-note">이 프로모션·대상 조합에 대한 유입 데이터가 아직 없습니다.</p>
  </div>`;
}

/* ---- 채널 체크리스트(내부/외부) — DATA.channelPrefs(Phase 1에서 이미 로드/저장 구현됨) 기반.
   TRAFFIC_INT_CATS/TRAFFIC_EXT_CATS는 분류(내부/외부 판정)에는 계속 쓰이지만, 화면 표시 목록은
   더 이상 이 하드코딩된 배열을 쓰지 않는다 — 사용자가 자유롭게 추가/제거한 채널만 표시한다. ---- */
function trackedChannels(category){
  return (DATA.channelPrefs||[]).filter(c=>c.category===category).sort((a,b)=>(a.order||0)-(b.order||0)).map(c=>c.channelName);
}
/* 채널 추가 시 자동완성 후보 — 현재 보고 있는 프로모션·대상의 실제 참조원(_refTotals) 중
   아직 추적하지 않는 것을 유입수 내림차순으로 최대 30개 제안한다(직접 입력도 항상 가능). */
function channelSuggestions(){
  if(!_trafficAggCache) return [];
  const cur=_trafficAggCache.agg.periodTotals.cur; if(!cur||!cur._refTotals) return [];
  const tracked=new Set([...trackedChannels('internal'), ...trackedChannels('external')]);
  return Object.keys(cur._refTotals)
    .filter(ref=>!tracked.has(ref))
    .sort((a,b)=>cur._refTotals[b]-cur._refTotals[a])
    .slice(0,30);
}
function renderChannelMgrHTML(category, mountId){
  const wrap=document.getElementById(mountId); if(!wrap) return;
  const tracked=(DATA.channelPrefs||[]).filter(c=>c.category===category).sort((a,b)=>(a.order||0)-(b.order||0));
  const sugg=channelSuggestions();
  const list=tracked.length? tracked.map(c=>`<span class="chan-chip">${escHtml(trafficCatLabel(c.channelName))}<button type="button" class="chan-del-btn" data-id="${c.id}" title="제거">✕</button></span>`).join('')
    : '<span class="muted-note">추가된 채널이 없습니다.</span>';
  const suggOpts=sugg.map(s=>{
    const v=(_trafficAggCache.agg.periodTotals.cur._refTotals||{})[s]||0;
    return `<option value="${escHtml(s)}">${escHtml(trafficCatLabel(s))} (${f0(v)})</option>`;
  }).join('');
  wrap.innerHTML=`
    <div class="chan-list">${list}</div>
    <button type="button" class="btn chan-add-btn" data-cat="${category}">+ 채널 추가</button>
    <div class="chan-add-wrap" style="display:none">
      <select class="chan-add-select"><option value="">실제 참조원에서 선택…</option>${suggOpts}</select>
      <input type="text" class="chan-add-input" placeholder="또는 채널명 직접 입력">
      <div class="memo-entry-actions">
        <button type="button" class="btn chan-add-save" data-cat="${category}">추가</button>
        <button type="button" class="btn chan-add-cancel">취소</button>
      </div>
    </div>`;
}
function wireChannelMgr(mountId){
  const wrap=document.getElementById(mountId); if(!wrap||wrap.dataset.chanWired) return;
  wrap.dataset.chanWired='1';
  wrap.addEventListener('change',(e)=>{
    const sel=e.target.closest('.chan-add-select'); if(!sel||!sel.value) return;
    wrap.querySelector('.chan-add-input').value=sel.value;
  });
  wrap.addEventListener('click', async (e)=>{
    const addBtn=e.target.closest('.chan-add-btn');
    const cancelBtn=e.target.closest('.chan-add-cancel');
    const saveBtn=e.target.closest('.chan-add-save');
    const delBtn=e.target.closest('.chan-del-btn');
    if(addBtn){
      wrap.querySelector('.chan-add-wrap').style.display='flex';
    } else if(cancelBtn){
      wrap.querySelector('.chan-add-wrap').style.display='none';
    } else if(saveBtn){
      const name=wrap.querySelector('.chan-add-input').value.trim();
      if(!name){ alert('채널명을 입력하거나 목록에서 선택해주세요.'); return; }
      saveBtn.disabled=true;
      try{
        await addChannelPref(saveBtn.dataset.cat, name);
        wrap.querySelector('.chan-add-wrap').style.display='none';
        renderF();
      }catch(err){ alert('채널 추가 실패: '+err.message); }
      finally{ saveBtn.disabled=false; }
    } else if(delBtn){
      if(!confirm('이 채널을 목록에서 제거할까요?')) return;
      delBtn.disabled=true;
      try{ await removeChannelPref(delBtn.dataset.id); renderF(); }
      catch(err){ alert('제거 실패: '+err.message); delBtn.disabled=false; }
    }
  });
}

/* ---- 컨트롤 초기화: 프로모션 드롭다운 채우기(데이터 있는 프로모션 우선 기본 선택) ---- */
function initTrafficControls(){
  const el=document.getElementById('f-promo'); if(!el) return;
  const list=trafficPromosSorted();
  const opts=list.map(p=>({v:p.id,t:p.label}));
  const withData=list.find(p=>hasTrafficData(trafficState.target,p.id)) || list.find(p=>hasTrafficData('shop',p.id));
  const def=(withData||list[0]||{}).id;
  const keep=el.value&&trafficPromoById(el.value)?el.value:def;
  fillSelect(el, opts, keep);
  trafficState.promoId=keep;
  renderTargetTabs();
}

/* ---- 탭 ⑥ 메인 렌더 ---- */
function renderF(){
  const promoSel=document.getElementById('f-promo'); if(!promoSel) return;
  if(promoSel.value) trafficState.promoId=promoSel.value;
  renderTargetTabs();
  updateArchiveButtonUI();
  renderMemoBox('traffic', memoCtxF());

  const p=trafficPromoById(trafficState.promoId);
  const bandEl=document.getElementById('f-band');
  if(!p){ if(bandEl) bandEl.innerHTML='<div class="muted-note">유입 분석용 프로모션 데이터가 없습니다.</div>'; return; }
  if(bandEl) bandEl.innerHTML=bandHTML([
    {k:'금번',s:p.start,e:p.end},
    {k:'직전',s:p.prevStart,e:p.prevEnd,note:p.prevId?trafficPromoLabelShort(p.prevId):''},
    {k:'전년',s:p.yoyStart,e:p.yoyEnd,note:p.yoyId?trafficPromoLabelShort(p.yoyId):''},
  ]);
  const badgeEl=document.getElementById('f-daybadge');
  const badge=promoDayBadge(p);
  if(badgeEl){ badgeEl.style.display=badge?'':'none'; badgeEl.textContent=badge; }

  const agg=getTrafficAgg(trafficState.target, p.id);
  const noteEl=document.getElementById('f-unit-note');
  if(noteEl) noteEl.textContent = trafficState.target==='shop'
    ? 'SHOP은 RMS 화면상 Top30 랭킹 합산 수치(アクセス人数 기준)이며, Top30 밖 롱테일은 "미분류"로 별도 표기됩니다.'
    : 'UV(ユニークユーザー数) 기준 전수 집계입니다.';

  const contentEl=document.getElementById('f-content'), emptyEl=document.getElementById('f-empty-state');
  if(!agg){
    if(contentEl) contentEl.style.display='none';
    if(emptyEl){
      emptyEl.style.display='';
      const isCustom=customTrafficCodes().includes(trafficState.target);
      emptyEl.innerHTML = isCustom ? renderTrafficEmptyState(trafficState.target, p.label) : renderTrafficGenericEmptyState();
    }
    _trafficAggCache=null;
    return;
  }
  if(contentEl) contentEl.style.display='';
  if(emptyEl) emptyEl.style.display='none';
  _trafficAggCache={agg,p};

  const dateSel=document.getElementById('f-date');
  if(dateSel){
    const dOpts=[{v:'__ALL__',t:'전체'}].concat(agg.daily.map(x=>({v:x.d, t:mdLabel(x.d)+' ('+(x.k+1)+'일차)'})));
    const today=todayStr();
    let wantDate=trafficState.date;
    if(!wantDate || (wantDate!=='__ALL__' && !agg.daily.some(x=>x.d===wantDate))){
      const todayRow=agg.daily.find(x=>x.d===today);
      wantDate = todayRow ? today : '__ALL__';
    }
    trafficState.date=wantDate;
    fillSelect(dateSel, dOpts, wantDate);
  }

  const k = trafficState.date==='__ALL__' ? -1 : agg.daily.findIndex(x=>x.d===trafficState.date);
  const view = k>=0 ? agg.daily[k] : {cur:agg.periodTotals.cur, prev:agg.periodTotals.prev, yoy:agg.periodTotals.yoy};
  const shareOf=(o,key)=> o&&o.total? o[key]/o.total : null;

  /* ===== 1. 누계 유입 실적 ===== */
  const kpiRows=[
    trafficRowHTML('전체유입', view.cur.total, view.prev&&view.prev.total, view.yoy&&view.yoy.total),
    trafficRowHTML('내부유입', view.cur.internal, view.prev&&view.prev.internal, view.yoy&&view.yoy.internal),
    trafficShareRowHTML('내부비중', shareOf(view.cur,'internal'), shareOf(view.prev,'internal'), shareOf(view.yoy,'internal')),
    trafficRowHTML('외부유입', view.cur.external, view.prev&&view.prev.external, view.yoy&&view.yoy.external),
    trafficShareRowHTML('외부비중', shareOf(view.cur,'external'), shareOf(view.prev,'external'), shareOf(view.yoy,'external')),
  ];
  const kpiEl=document.getElementById('f-kpi');
  if(kpiEl) kpiEl.innerHTML=TRAFFIC_TABLE_HEAD+'<tbody>'+kpiRows.join('')+'</tbody>';

  /* ===== 2. 일자별 유입 실적 — 누계와 동일한 5개 지표를 날짜별 행으로(③탭과 동일한 패턴) ===== */
  const dailyMetrics=[
    {l:'전체유입', get:a=>a.total, ratio:false},
    {l:'내부유입', get:a=>a.internal, ratio:false},
    {l:'내부비중', get:a=>a.total?a.internal/a.total:null, ratio:true},
    {l:'외부유입', get:a=>a.external, ratio:false},
    {l:'외부비중', get:a=>a.total?a.external/a.total:null, ratio:true},
  ];
  const dailyEl=document.getElementById('f-daily');
  if(dailyEl){
    let t=cmpDailyHead(dailyMetrics.map(m=>m.l))+'<tbody>';
    agg.daily.forEach(x=>{
      const cls=x.d===trafficState.date?' class="total"':'';
      t+=`<tr${cls} data-date="${x.d}"><td class="datecell">${mdLabel(x.d)}(${x.k+1}일차)</td>`+
        dailyMetrics.map(m=>cmp7TDs(m.get(x.cur), x.prev?m.get(x.prev):null, x.yoy?m.get(x.yoy):null, m.ratio?fp0:f0, m.ratio)).join('')+
        '</tr>';
    });
    const pt=agg.periodTotals;
    t+=`<tr class="total"><td>합계</td>`+
      dailyMetrics.map(m=>cmp7TDs(m.get(pt.cur), pt.prev?m.get(pt.prev):null, pt.yoy?m.get(pt.yoy):null, m.ratio?fp0:f0, m.ratio)).join('')+
      '</tr></tbody>';
    dailyEl.innerHTML=t;
  }
  wireTrafficDailyClicks('f-daily');

  /* ===== 4/5. 내부/외부 채널별 실적 — 사용자가 추가한 채널만(기타 없음) + 합계 자동계산 ===== */
  const chanVal=(o,name)=> (o&&o._refTotals)? (o._refTotals[name]||0) : 0;
  function renderChanTable(category){
    const names=trackedChannels(category);
    if(!names.length) return TRAFFIC_TABLE_HEAD+'<tbody><tr><td colspan="8"><span class="muted-note">추가된 채널이 없습니다. 위 "+ 채널 추가"로 원하는 채널을 등록해보세요.</span></td></tr></tbody>';
    const rows=names.map(name=>trafficRowHTML(trafficCatLabel(name), chanVal(view.cur,name), view.prev&&chanVal(view.prev,name), view.yoy&&chanVal(view.yoy,name)));
    const total=o=>names.reduce((s,n)=>s+chanVal(o,n),0);
    rows.push(trafficRowHTML('합계', total(view.cur), view.prev&&total(view.prev), view.yoy&&total(view.yoy)));
    return TRAFFIC_TABLE_HEAD+'<tbody>'+rows.join('')+'</tbody>';
  }
  renderChannelMgrHTML('internal','f-chan-mgr-int');
  renderChannelMgrHTML('external','f-chan-mgr-ext');
  wireChannelMgr('f-chan-mgr-int');
  wireChannelMgr('f-chan-mgr-ext');
  const catIntEl=document.getElementById('f-cat-int'); if(catIntEl) catIntEl.innerHTML=renderChanTable('internal');
  const catExtEl=document.getElementById('f-cat-ext'); if(catExtEl) catExtEl.innerHTML=renderChanTable('external');

  const intNames=trackedChannels('internal'), extNames=trackedChannels('external');
  const intGetVal=(a,c)=>chanVal(a,c), extGetVal=(a,c)=>chanVal(a,c);
  const dIntChanEl=document.getElementById('f-daily-int-channels');
  if(dIntChanEl){
    dIntChanEl.innerHTML = intNames.length? trafficChannelDailyTableHTML(agg, intNames, intGetVal, 'int') : '<tbody><tr><td><span class="muted-note">추가된 채널이 없습니다.</span></td></tr></tbody>';
    dIntChanEl.querySelectorAll('.trf-chan-toggle').forEach(el=>el.onclick=()=>{ trafficChanExpand.int[el.dataset.chan]=!trafficChanExpand.int[el.dataset.chan]; renderF(); });
  }
  const dIntChanDetailEl=document.getElementById('f-daily-int-channels-detail');
  if(dIntChanDetailEl) dIntChanDetailEl.innerHTML=trafficChannelDetailHTML(agg, intNames, intGetVal, 'int');
  const dExtChanEl=document.getElementById('f-daily-ext-channels');
  if(dExtChanEl){
    dExtChanEl.innerHTML = extNames.length? trafficChannelDailyTableHTML(agg, extNames, extGetVal, 'ext') : '<tbody><tr><td><span class="muted-note">추가된 채널이 없습니다.</span></td></tr></tbody>';
    dExtChanEl.querySelectorAll('.trf-chan-toggle').forEach(el=>el.onclick=()=>{ trafficChanExpand.ext[el.dataset.chan]=!trafficChanExpand.ext[el.dataset.chan]; renderF(); });
  }
  const dExtChanDetailEl=document.getElementById('f-daily-ext-channels-detail');
  if(dExtChanDetailEl) dExtChanDetailEl.innerHTML=trafficChannelDetailHTML(agg, extNames, extGetVal, 'ext');
  ['f-daily-int-channels','f-daily-ext-channels'].forEach(wireTrafficDailyClicks);

  if(document.getElementById('f-chart')){
    const css=getComputedStyle(document.documentElement);
    setChart('f-chart', {
      type:'line',
      data:{ labels: agg.daily.map(x=>mdLabel(x.d)),
        datasets:[
          {label:'전체', data:agg.daily.map(x=>x.cur.total), borderColor:css.getPropertyValue('--blue')||'#378ADD', tension:.25, pointRadius:3, _getVal:a=>a.total},
          {label:'내부', data:agg.daily.map(x=>x.cur.internal), borderColor:css.getPropertyValue('--teal')||'#1D9E75', tension:.25, pointRadius:3, _getVal:a=>a.internal},
          {label:'외부', data:agg.daily.map(x=>x.cur.external), borderColor:css.getPropertyValue('--coral')||'#D85A30', tension:.25, pointRadius:3, _getVal:a=>a.external},
        ]},
      options:{ responsive:true, maintainAspectRatio:false, interaction:{mode:'index',intersect:false},
        plugins:{legend:{display:false}, tooltip:trafficTooltipConfig(agg)}, scales:{y:{beginAtZero:true}},
        onClick:(evt,elements)=>{ if(elements&&elements.length){ const idx=elements[0].index; trafficState.date=agg.daily[idx].d; renderF(); } } }
    });
  }
  if(document.getElementById('f-chart-int')){
    setChart('f-chart-int', {
      type:'line',
      data:{ labels: agg.daily.map(x=>mdLabel(x.d)),
        datasets: intNames.map((c,i)=>({label:trafficCatLabel(c), data:agg.daily.map(x=>chanVal(x.cur,c)), borderColor:TRAFFIC_COLORS[i%TRAFFIC_COLORS.length], tension:.25, pointRadius:2, _getVal:a=>chanVal(a,c)})) },
      options:{ responsive:true, maintainAspectRatio:false, interaction:{mode:'index',intersect:false},
        plugins:{legend:{display:true, position:'bottom', labels:{boxWidth:10,font:{size:10}}}, tooltip:trafficTooltipConfig(agg)}, scales:{y:{beginAtZero:true}} }
    });
  }
  if(document.getElementById('f-chart-ext')){
    setChart('f-chart-ext', {
      type:'line',
      data:{ labels: agg.daily.map(x=>mdLabel(x.d)),
        datasets: extNames.map((c,i)=>({label:trafficCatLabel(c), data:agg.daily.map(x=>chanVal(x.cur,c)), borderColor:TRAFFIC_COLORS[i%TRAFFIC_COLORS.length], tension:.25, pointRadius:2, _getVal:a=>chanVal(a,c)})) },
      options:{ responsive:true, maintainAspectRatio:false, interaction:{mode:'index',intersect:false},
        plugins:{legend:{display:true, position:'bottom', labels:{boxWidth:10,font:{size:10}}}, tooltip:trafficTooltipConfig(agg)}, scales:{y:{beginAtZero:true}} }
    });
  }

  renderFInsight(agg);
  renderFTop30();
  wireTrafficCSV(view, agg);
}

/* ---- Top30: 검색 + 정렬(유입수/비중) 토글 ---- */
function renderFTop30(){
  const el=document.getElementById('f-top30-tbl'); if(!el||!_trafficAggCache) return;
  const {agg}=_trafficAggCache;
  const k = trafficState.date==='__ALL__' ? -1 : agg.daily.findIndex(x=>x.d===trafficState.date);
  const top = k>=0 ? agg.daily[k].cur.top : agg.periodTotals.cur.top;
  const q=(document.getElementById('f-top-search')?document.getElementById('f-top-search').value:'').trim().toLowerCase();
  const sortKey=document.getElementById('f-top-sort')?document.getElementById('f-top-sort').value:'val';
  let rows=top.filter(r=>!q||r.ref.toLowerCase().includes(q));
  rows=rows.slice().sort((a,b)=>b[sortKey]-a[sortKey]);
  let t='<thead><tr><th>순위</th><th>참조원</th><th>구분</th><th>유입수</th><th>비중</th></tr></thead><tbody>';
  rows.forEach((r,i)=>{ t+=`<tr><td>${i+1}</td><td>${r.ref}</td><td>${r.area||'—'}</td><td>${f0(r.val)}</td><td>${fp0(r.share)}</td></tr>`; });
  el.innerHTML=t+'</tbody>';
}

/* ---- AI 분석(규칙 기반) — 기존 탭③의 renderSalesInsightHTML과 동일한 mkItem/insight-item 스타일 재사용, 전체 기간이 아니라
   "선택 날짜" 및 "현재 진행일차까지 누계" 기준으로 분석. 전체/내부/외부 총계뿐 아니라 사용자가 추가한 채널별
   증감 기여도까지 비교해 원인을 서술한다. ---- */
function sumTrafficAcc(list){
  const acc={total:0, internal:0, external:0, byCat:{}, byCatExt:{}, otherInt:0, otherExt:0, unclassified:0, _refTotals:{}};
  list.forEach(a=>{
    if(!a) return;
    acc.total+=a.total||0; acc.internal+=a.internal||0; acc.external+=a.external||0;
    acc.otherInt+=a.otherInt||0; acc.otherExt+=a.otherExt||0; acc.unclassified+=a.unclassified||0;
    Object.keys(a.byCat||{}).forEach(k=>acc.byCat[k]=(acc.byCat[k]||0)+a.byCat[k]);
    Object.keys(a.byCatExt||{}).forEach(k=>acc.byCatExt[k]=(acc.byCatExt[k]||0)+a.byCatExt[k]);
    Object.keys(a._refTotals||{}).forEach(k=>acc._refTotals[k]=(acc._refTotals[k]||0)+a._refTotals[k]);
  });
  return acc;
}
function trafficChannelDeltas(cur, base){
  if(!base) return [];
  // 하드코딩된 채널 목록 대신, 사용자가 실제로 추가/추적 중인 채널만 비교한다(화면에 보이는 채널과 AI 코멘트를 일치시킴).
  const names=[...new Set([...trackedChannels('internal'), ...trackedChannels('external')])];
  const list=names.map(name=>({label:name, cur:(cur._refTotals&&cur._refTotals[name])||0, base:(base._refTotals&&base._refTotals[name])||0}));
  return list.map(x=>({...x, diff:x.cur-x.base}));
}
function buildTrafficInsightItems(cur, prev, yoy){
  const items=[];
  const basisOf=(curV,prevV,yoyV)=>{
    const pp=pctChangeSafe(curV,prevV); if(pp!=null) return {basis:'직전',pct:pp,baseV:prevV};
    const py=pctChangeSafe(curV,yoyV); if(py!=null) return {basis:'전년',pct:py,baseV:yoyV};
    return null;
  };
  const totalB=basisOf(cur.total, prev&&prev.total, yoy&&yoy.total);
  if(totalB){
    const dir=totalB.pct>=0?'증가':'감소';
    items.push(mkItem(Math.abs(totalB.pct)>=20?(totalB.pct<0?'warn':'good'):'plain',
      `전체유입이 ${totalB.basis} 대비 <b>${fmtSigned(totalB.pct)}</b> ${dir}했습니다 (${f0(totalB.baseV)} → ${f0(cur.total)}).`));
  } else {
    items.push(mkItem('plain','비교 가능한 직전/전년 데이터가 없어 분석을 생성할 수 없습니다.'));
    return items;
  }
  const baseObj=prev||yoy, baseLabel=prev?'직전':'전년';
  if(baseObj && baseObj.total && cur.total){
    const curShare=cur.internal/cur.total, baseShare=baseObj.internal/baseObj.total;
    const ppDiff=(curShare-baseShare)*100;
    if(Math.abs(ppDiff)>=5){
      items.push(mkItem('plain', `내부 유입 비중이 ${baseLabel} 대비 ${ppDiff>=0?'+':''}${ppDiff.toFixed(1)}%p ${ppDiff>=0?'상승':'하락'}했습니다 (${fp0(baseShare)} → ${fp0(curShare)}).`));
    }
  }
  const extB=basisOf(cur.external, prev&&prev.external, yoy&&yoy.external);
  if(extB && Math.abs(extB.pct)>=15) items.push(mkItem(extB.pct<0?'warn':'plain', `외부유입이 ${extB.basis} 대비 ${fmtSigned(extB.pct)} ${extB.pct>=0?'증가':'감소'}했습니다.`));
  const intB=basisOf(cur.internal, prev&&prev.internal, yoy&&yoy.internal);
  if(intB && Math.abs(intB.pct)>=15) items.push(mkItem(intB.pct<0?'warn':'plain', `내부유입이 ${intB.basis} 대비 ${fmtSigned(intB.pct)} ${intB.pct>=0?'증가':'감소'}했습니다.`));

  const deltas=trafficChannelDeltas(cur, baseObj);
  if(deltas.length){
    const sorted=deltas.slice().sort((a,b)=>b.diff-a.diff);
    const best=sorted[0], worst=sorted[sorted.length-1];
    if(best && best.diff>0){
      items.push(mkItem('good', `${baseLabel} 대비 가장 크게 증가한 채널은 <b>${best.label}</b>입니다 (+${f0(best.diff)}, ${f0(best.base)} → ${f0(best.cur)}).`));
    }
    if(worst && worst.diff<0 && worst.label!==(best&&best.label)){
      items.push(mkItem(Math.abs(worst.diff)>=Math.abs((best&&best.diff)||0)?'warn':'plain', `${baseLabel} 대비 가장 크게 감소한 채널은 <b>${worst.label}</b>입니다 (${f0(worst.diff)}, ${f0(worst.base)} → ${f0(worst.cur)}).`));
    }
  }
  return items;
}
function trafficInsightItemsHTML(items){
  return items.map(it=>`<div class="insight-item${it.cls==='warn'?' warn':it.cls==='good'?' good':''}"><span class="ic">${it.icon}</span><span>${it.text}</span></div>`).join('');
}
/* 프로모션 종료 기록 — 이 대시보드는 서버/DB가 없는 정적 사이트라 브라우저 localStorage에 저장한다.
   같은 브라우저에서만 유지되며(기기·브라우저 간 공유 안 됨), 저장 시점의 AI 분석 문구를 그대로 고정해
   이후 규칙이 바뀌어도 "그날 봤던 분석"이 그대로 재조회되도록 한다. */
const TRAFFIC_ARCHIVE_KEY='rakutenTrafficArchive_v1';
function loadTrafficArchive(){ try{ return JSON.parse(localStorage.getItem(TRAFFIC_ARCHIVE_KEY)||'{}'); }catch(e){ return {}; } }
function saveTrafficArchive(obj){ try{ localStorage.setItem(TRAFFIC_ARCHIVE_KEY, JSON.stringify(obj)); }catch(e){ console.warn('[유입 분석] 기록 저장 실패(localStorage 사용 불가):', e.message); } }
function fmtArchiveTime(iso){
  const d=new Date(iso); const p=n=>String(n).padStart(2,'0');
  return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}
/* 저장 버튼 상태를 현재 선택된 프로모션·대상 기준으로 즉시 반영 — 클릭 직후 결과를 바로 알 수 있도록
   renderF()가 실행될 때마다(=선택이 바뀔 때마다, 저장 직후에도) 매번 다시 계산한다. */
function updateArchiveButtonUI(){
  const btn=document.getElementById('f-archive-btn'); if(!btn) return;
  const statusEl=document.getElementById('f-archive-status');
  const archived=loadTrafficArchive()[trafficState.target+':'+trafficState.promoId];
  if(archived){
    btn.textContent='✅ 기록 저장 완료 (다시 저장)';
    if(statusEl){ statusEl.style.display=''; statusEl.textContent='마지막 저장: '+fmtArchiveTime(archived.archivedAt); }
  } else {
    btn.textContent='🏁 프로모션 종료(기록 저장)';
    if(statusEl){ statusEl.style.display='none'; statusEl.textContent=''; }
  }
}
function archiveCurrentPromo(){
  const p=trafficPromoById(trafficState.promoId); if(!p) return;
  const agg=getTrafficAgg(trafficState.target, p.id); if(!agg||!agg.daily.length) return;
  const archive=loadTrafficArchive();
  const cumCur=sumTrafficAcc(agg.daily.map(x=>x.cur));
  const prevRows=agg.daily.map(x=>x.prev).filter(Boolean), yoyRows=agg.daily.map(x=>x.yoy).filter(Boolean);
  const cumItems=buildTrafficInsightItems(cumCur, prevRows.length?sumTrafficAcc(prevRows):null, yoyRows.length?sumTrafficAcc(yoyRows):null);
  const lastDay=agg.daily[agg.daily.length-1];
  const dayItems=buildTrafficInsightItems(lastDay.cur, lastDay.prev, lastDay.yoy);
  archive[trafficState.target+':'+p.id]={archivedAt:new Date().toISOString(), promoLabel:p.label, cumItems, dayItems, lastDate:lastDay.d};
  saveTrafficArchive(archive);
  renderF();
}
function renderFInsight(agg){
  const dayWrap=document.getElementById('f-ai-daily'), cumWrap=document.getElementById('f-ai-cum');
  if(!dayWrap && !cumWrap) return;
  const archive=loadTrafficArchive();
  const archived=archive[trafficState.target+':'+trafficState.promoId];

  let dayIdx = trafficState.date==='__ALL__' ? agg.daily.length-1 : agg.daily.findIndex(x=>x.d===trafficState.date);
  if(dayIdx<0) dayIdx=agg.daily.length-1;
  const dayRow=agg.daily[dayIdx];
  const isLastDay = dayRow && agg.daily.length && dayRow.k===agg.daily.length-1;

  const dayItems = (archived && isLastDay) ? archived.dayItems : (dayRow? buildTrafficInsightItems(dayRow.cur, dayRow.prev, dayRow.yoy) : []);

  /* 누계는 "오늘 날짜"가 아니라 "지금 선택된 날짜(dayIdx)"까지 누적한다 — 예: 3일차 선택 시 1~3일차 누적.
     단, 종료 기록(archived)이 있으면 날짜 선택과 무관하게 항상 전체 기간(1~마지막일) 고정 분석을 보여준다. */
  let upToK = archived ? (agg.daily.length-1) : dayIdx;
  let cumItems;
  if(archived){ cumItems=archived.cumItems; }
  else{
    const cumCur=sumTrafficAcc(agg.daily.slice(0,upToK+1).map(x=>x.cur));
    const prevRows=agg.daily.slice(0,upToK+1).map(x=>x.prev).filter(Boolean), yoyRows=agg.daily.slice(0,upToK+1).map(x=>x.yoy).filter(Boolean);
    cumItems=buildTrafficInsightItems(cumCur, prevRows.length?sumTrafficAcc(prevRows):null, yoyRows.length?sumTrafficAcc(yoyRows):null);
  }

  const badge = archived? `<div class="pill" style="margin-bottom:8px">📌 ${new Date(archived.archivedAt).toLocaleDateString('ko-KR')} 종료 기록됨 — 저장된 분석 표시 중</div>` : '';
  if(dayWrap) dayWrap.innerHTML = `${badge}<div class="muted-note" style="margin-bottom:8px">${dayRow?`${dayRow.d} · ${dayRow.k+1}일차`:''}</div><div class="insight-wrap">${trafficInsightItemsHTML(dayItems)}</div>`;
  if(cumWrap) cumWrap.innerHTML = `<div class="muted-note" style="margin-bottom:8px">1일차~${upToK+1}일차 누적</div><div class="insight-wrap">${trafficInsightItemsHTML(cumItems)}</div>`;
}

/* ---- CSV 다운로드 버튼 배선 (매 렌더마다 현재 표시 데이터로 다시 연결) ---- */
function wireTrafficCSV(view, agg){
  const shareOf=(o,key)=> o&&o.total? o[key]/o.total : null;
  const pct=v=>v==null?'':(v*100).toFixed(1);
  const kpiBtn=document.getElementById('f-csv-kpi');
  if(kpiBtn) kpiBtn.onclick=()=>{
    const rows=[
      ['전체유입', view.cur.total, view.prev?view.prev.total:'', view.yoy?view.yoy.total:''],
      ['내부유입', view.cur.internal, view.prev?view.prev.internal:'', view.yoy?view.yoy.internal:''],
      ['내부 비중(%)', pct(shareOf(view.cur,'internal')), pct(shareOf(view.prev,'internal')), pct(shareOf(view.yoy,'internal'))],
      ['외부유입', view.cur.external, view.prev?view.prev.external:'', view.yoy?view.yoy.external:''],
      ['외부 비중(%)', pct(shareOf(view.cur,'external')), pct(shareOf(view.prev,'external')), pct(shareOf(view.yoy,'external'))],
    ];
    downloadTrafficCSV(`유입분석_요약_${trafficState.target}_${trafficState.promoId}.csv`, ['구분','금번','직전','전년'], rows);
  };
  function chanRows(category){
    const names=trackedChannels(category);
    return names.map(name=>[name, (view.cur._refTotals&&view.cur._refTotals[name])||0]);
  }
  const catIntBtn=document.getElementById('f-csv-cat-int');
  if(catIntBtn) catIntBtn.onclick=()=>downloadTrafficCSV(`유입분석_내부채널상세_${trafficState.target}_${trafficState.promoId}.csv`, ['채널','유입수'], chanRows('internal'));
  const catExtBtn=document.getElementById('f-csv-cat-ext');
  if(catExtBtn) catExtBtn.onclick=()=>downloadTrafficCSV(`유입분석_외부채널상세_${trafficState.target}_${trafficState.promoId}.csv`, ['채널','유입수'], chanRows('external'));
  const dailyHead=['날짜','금번','직전','전년','직전차','직전비','전년차','전년비'];
  function dailyRows(valFn){
    return agg.daily.map(x=>{
      const cur=valFn(x.cur), prev=x.prev?valFn(x.prev):null, yoy=x.yoy?valFn(x.yoy):null;
      const dpA=diffAbsTraffic(cur,prev), dyA=diffAbsTraffic(cur,yoy);
      const dp=delta(cur,prev), dy=delta(cur,yoy);
      return [x.d, cur, prev!=null?prev:'', yoy!=null?yoy:'', dpA.t, dp.t, dyA.t, dy.t];
    });
  }
  const dBtn=document.getElementById('f-csv-daily');
  if(dBtn) dBtn.onclick=()=>downloadTrafficCSV(`유입분석_일별_${trafficState.target}_${trafficState.promoId}.csv`, dailyHead, dailyRows(a=>a.total));
  const intChanBtn=document.getElementById('f-csv-daily-int-channels');
  if(intChanBtn) intChanBtn.onclick=()=>{
    const cats=trackedChannels('internal');
    const rows=agg.daily.map(x=>[x.d, ...cats.map(c=>(x.cur._refTotals&&x.cur._refTotals[c])||0)]);
    downloadTrafficCSV(`유입분석_일별_내부채널_${trafficState.target}_${trafficState.promoId}.csv`, ['날짜',...cats], rows);
  };
  const extChanBtn=document.getElementById('f-csv-daily-ext-channels');
  if(extChanBtn) extChanBtn.onclick=()=>{
    const cats=trackedChannels('external');
    const rows=agg.daily.map(x=>[x.d, ...cats.map(c=>(x.cur._refTotals&&x.cur._refTotals[c])||0)]);
    downloadTrafficCSV(`유입분석_일별_외부채널_${trafficState.target}_${trafficState.promoId}.csv`, ['날짜',...cats], rows);
  };
  const topBtn=document.getElementById('f-csv-top30');
  if(topBtn) topBtn.onclick=()=>{
    const k = trafficState.date==='__ALL__' ? -1 : agg.daily.findIndex(x=>x.d===trafficState.date);
    const top = k>=0 ? agg.daily[k].cur.top : agg.periodTotals.cur.top;
    const rows=top.map((r,i)=>[i+1, r.ref, r.area||'', r.val, (r.share*100).toFixed(1)+'%']);
    downloadTrafficCSV(`유입분석_Top30_${trafficState.target}_${trafficState.promoId}_${trafficState.date}.csv`, ['순위','참조원','구분','유입수','비중'], rows);
  };
}

/* ---- 이벤트 배선 (신규 컨트롤 전용 — 기존 배선 블록은 무변경) ---- */
if(document.getElementById('f-promo')) document.getElementById('f-promo').onchange=function(){ trafficState.promoId=this.value; trafficState.date='__ALL__'; renderF(); };
if(document.getElementById('f-date')) document.getElementById('f-date').onchange=function(){ trafficState.date=this.value; renderF(); };
if(document.getElementById('f-top-search')) document.getElementById('f-top-search').oninput=renderFTop30;
if(document.getElementById('f-top-sort')) document.getElementById('f-top-sort').onchange=renderFTop30;
if(document.getElementById('f-archive-btn')) document.getElementById('f-archive-btn').onclick=function(){
  if(confirm('현재 프로모션을 종료 기록으로 저장할까요? 저장 시점의 요약·AI 분석이 고정되어 이후에도 그대로 다시 조회됩니다.')) archiveCurrentPromo();
};

/* ---- 데이터 로딩 확장: 기존 loadLive()는 한 글자도 수정하지 않고, GitHub에서 한 번 더 받아 traffic만 별도로 채운다.
   (fetchGitHubData는 순수 GET이라 한 번 더 호출해도 부작용 없음 — 기존 함수 그대로 재사용) ---- */
function loadTrafficFromJson_(json){
  const t=(json&&json.traffic)||{};
  DATA.traffic={
    promos: parseTrafficPromos(t.promos||[]),
    shop: t.shop||{},
    // 고정 4개 SKU를 기본값으로 깔되, 그외_raw(B2 상품코드)로 등록된 동적 SKU 키도
    // (t.sku에 이미 함께 들어있으므로) 그대로 보존한다 — 특정 4개만 골라 복사하면
    // 동적으로 추가된 SKU들이 매 새로고침마다 통째로 사라지는 문제가 있었다.
    sku: Object.assign({yp0001:{},yp3755:{},ys0211:{},ybox2508:{}}, t.sku||{}),
    other: t.other||{},
    dynamicSkuCodes: Array.isArray(t.dynamicSkuCodes)? t.dynamicSkuCodes : [],
  };
  trafficParsedCache={};
  initTrafficControls();
}
const _rakutenTrafficOrigLoadLive=loadLive;
loadLive=async function(){
  await _rakutenTrafficOrigLoadLive();
  try{
    const json=await fetchGitHubData();
    loadTrafficFromJson_(json);
  }catch(e){
    console.warn('[유입 분석] traffic 데이터 로드 실패 — 이전 상태 유지:', e.message);
  }
  if(activeTab===5) renderF();
};
if(document.getElementById('refresh')) document.getElementById('refresh').onclick=loadLive;

initTrafficControls();
wireTargetTabs();
wireChannelMgr('f-chan-mgr-int');
wireChannelMgr('f-chan-mgr-ext');
/* ============================================================
   신규 기능 끝 — 여기까지 전부 추가된 코드. renderTab()에 renderF를
   연결하는 마지막 한 줄은 이 구현이 검증된 뒤 별도로 진행합니다.
   ============================================================ */

/* ============================================================
   신규 기능: 탭 ⑦ 어필리에이트 분석 (기존 코드/DATA/탭·함수는 전혀 수정하지 않고 전부 새로 추가)
   데이터 출처: data.json의 sheets.affiliate (시트명: 어필리에이트_RAW)
     A~N열 = 라쿠텐 어필리에이트 성과 RAW (일자~商品種別)
     P~Z열 = 같은 시트의 프로모션 설정 테이블 (프로모션명~전년 종료일 · 프로모션_항목과 동일 개념)
   ============================================================ */

if(!DATA.affiliate) DATA.affiliate={rows:[], promos:[]};

/* 요율(%) 비교 오차 허용치 — 부동소수점 오차 흡수용 */
const AFF_TIER_TOL=0.05;
/* S/T열(일반%·우수%)과 I열(料率)이 "3"처럼 정수%로도, "0.03"처럼 분수로도 입력될 수 있어
   1보다 작은 값은 ×100 해서 항상 같은 스케일(퍼센트 숫자)로 맞춘다. */
function affPctScale(n){ if(n==null||!isFinite(n)) return null; return (n>0 && n<1) ? n*100 : n; }
/* 셀이 비어있으면(미설정) null, 값이 있으면 %스케일 숫자 — "0%"와 "미설정"을 구분하기 위함 */
function affRateOrNull(cell){ if(!cell) return null; if(nstr(cell)==='') return null; return affPctScale(nnum(cell)); }

/* 어필리에이트_RAW 시트 원본 셀 배열 → {rows, promos} */
function parseAffiliateSheet(cells){
  const all=cellsOf(cells);
  const rows=[];
  all.forEach(r=>{
    const d=ndate(r[0]); if(!d) return;
    const status=nnum(r[10]);
    if(status===2) return; // 파기(2)만 제외 — 미확정(0)·확정(1)·공백은 모두 집계에 포함
    const sku=nstr(r[2])||'(SKU 미상)';
    rows.push({
      d, sku,
      rev:nnum(r[7]),
      ratePct:affPctScale(nnum(r[8])),
      fee:nnum(r[9]),
      clickDev:nnum(r[11]), buyDev:nnum(r[12]), prodType:nnum(r[13]),
    });
  });
  const promos=[];
  all.forEach(r=>{
    const nm=nstr(r[15]); if(!nm||nm==='프로모션명') return;
    const start=ndate(r[20]); if(!start) return;
    const yy=String(Math.round(nnum(r[16]))).slice(-2);
    const mm=String(Math.round(nnum(r[17])));
    const prevStart=ndate(r[22]), prevEnd=ndate(r[23]);
    const yoyStart=ndate(r[24]), yoyEnd=ndate(r[25]);
    const o={
      id:`${yy}-${mm}-${nm}`, label:`${yy}년 ${mm}월 ${nm}`, type:nm, year:yy,
      start, end:ndate(r[21])||start,
      generalRate:affRateOrNull(r[18]), premiumRate:affRateOrNull(r[19]),
    };
    if(prevStart){ o.prevStart=prevStart; o.prevEnd=prevEnd||prevStart; }
    if(yoyStart){ o.yoyStart=yoyStart; o.yoyEnd=yoyEnd||yoyStart; }
    promos.push(o);
  });
  derivePrevYoy(promos); // 시트에 직전·전년이 비어있을 때만 동일 프로모션명 기준으로 자동 보강
  return {rows, promos};
}

/* ---- 집계 헬퍼 ---- */
const affRange=(s,e)=>DATA.affiliate.rows.filter(r=>r.d>=s&&r.d<=e);
function affSum(rows){ let rev=0,fee=0; rows.forEach(r=>{rev+=r.rev; fee+=r.fee;}); return {rev, fee, n:rows.length}; }
const affAdRatio=a=>a.rev? a.fee/a.rev : 0;      // 광고비율 = 수수료/매출
const affRoas=a=>a.fee? a.rev/a.fee : 0;         // ROAS = 매출/수수료
const affRoasPct=a=>f0(affRoas(a)*100)+'%';   // 표시 전용 — 계산은 affRoas() 그대로, 형식만 %(정수, 천단위 콤마)로 변환
const affFeePerN=a=>a.n? a.fee/a.n : 0;          // 건당 수수료

/* row 하나가 일반/우수/기타(기본 제휴요율) 중 어디에 해당하는지, 해당 프로모션의 S/T열 기준으로 판정 */
function affTierOf(row, promo){
  if(promo.generalRate!=null && Math.abs(row.ratePct-promo.generalRate)<=AFF_TIER_TOL) return 'general';
  if(promo.premiumRate!=null && Math.abs(row.ratePct-promo.premiumRate)<=AFF_TIER_TOL) return 'premium';
  return 'other';
}
function affSplitByTier(rows, promo){
  const g=[],p=[],o=[];
  rows.forEach(r=>{ const t=affTierOf(r,promo); (t==='general'?g:t==='premium'?p:o).push(r); });
  return {general:affSum(g), premium:affSum(p), other:affSum(o)};
}
function affBySku(rows){
  const m={};
  rows.forEach(r=>{ (m[r.sku]=m[r.sku]||[]).push(r); });
  return Object.keys(m).map(sku=>({sku, ...affSum(m[sku])}));
}
function affDayMapBuild(){
  const m={};
  DATA.affiliate.rows.forEach(r=>{
    if(!m[r.d]) m[r.d]={d:r.d, rev:0, fee:0, n:0};
    m[r.d].rev+=r.rev; m[r.d].fee+=r.fee; m[r.d].n+=1;
  });
  return m;
}
/* start부터 ML일차까지의 시계열 — 해당 기간 실제 길이(ownLen)를 넘어서면 null로 패딩해
   다음 기간의 실제 데이터가 섞여 들어가는 것을 막는다 (기존 tab④ elapsed()와 동일한 철학) */
function affElapsedSeries(start, ownLen, ML, getter, dm){
  const out=[];
  for(let k=0;k<ML;k++){
    if(k<ownLen){ const r=dm[addDays(start,k)]; out.push(r?getter(r):0); }
    else out.push(null);
  }
  return out;
}

/* ---- 프로모션 드롭다운(연도→프로모션) ---- */
const affPromosSorted=()=>(DATA.affiliate.promos||[]).slice().sort((a,b)=>b.start.localeCompare(a.start));
const affPromoById=id=>(DATA.affiliate.promos||[]).find(p=>p.id===id);
const affPromoLabelShort=id=>{const q=affPromoById(id); return q? (q.year+'.'+(+q.start.slice(5,7))+' '+q.type) : '';};

let affState={year:'', promoId:''};
let afSummaryYear=''; // 전체 프로모션 현황(연도·월별) 테이블 전용 — 위 af-year/af-promo와 독립적인 선택
function initAffControls(){
  const yearSel=document.getElementById('af-year'), promoSel=document.getElementById('af-promo');
  if(!yearSel||!promoSel) return;
  const years=[...new Set(affPromosSorted().map(p=>'20'+p.year))].sort().reverse();
  const keepY=(affState.year&&years.includes(affState.year))?affState.year:(years[0]||'');
  fillSelect(yearSel, years.map(y=>({v:y,t:y+'년'})), keepY);
  affState.year=keepY;
  const list=affPromosSorted().filter(p=>('20'+p.year)===affState.year);
  const keepP=(affState.promoId&&list.some(p=>p.id===affState.promoId))?affState.promoId:(list[0]?list[0].id:'');
  fillSelect(promoSel, list.map(p=>({v:p.id,t:p.label})), keepP);
  affState.promoId=keepP;
  yearSel.onchange=function(){
    affState.year=yearSel.value;
    const l=affPromosSorted().filter(p=>('20'+p.year)===affState.year);
    affState.promoId=l[0]?l[0].id:'';
    fillSelect(promoSel, l.map(p=>({v:p.id,t:p.label})), affState.promoId);
    renderAF();
  };
  promoSel.onchange=function(){ affState.promoId=promoSel.value; renderAF(); };

  const summarySel=document.getElementById('af-summary-year');
  if(summarySel){
    const keepSY=(afSummaryYear&&years.includes(afSummaryYear))?afSummaryYear:(years[0]||'');
    fillSelect(summarySel, years.map(y=>({v:y,t:y+'년'})), keepSY);
    afSummaryYear=keepSY;
    summarySel.onchange=function(){ afSummaryYear=summarySel.value; renderAffSummaryTable(); };
  }
}

/* ---- AI 분석 (규칙 기반, 외부 API 호출 없음 — 기존 renderSalesInsightHTML과 동일한 방식) ---- */
function renderAffiliateInsightHTML(p, prevPromo, cur, prev, yoy, curTier, skuRanking){
  const items=[];
  const roasCur=affRoas(cur), roasPrev=prev?affRoas(prev):null, roasYoy=yoy?affRoas(yoy):null;
  const roasPChg=pctChangeSafe(roasCur, roasPrev);
  const roasYChg=pctChangeSafe(roasCur, roasYoy);
  const ordP=pctChangeSafe(cur.n, prev?prev.n:null);
  const feeP=pctChangeSafe(cur.fee, prev?prev.fee:null);
  const genPrevRate=prevPromo?prevPromo.generalRate:null, premPrevRate=prevPromo?prevPromo.premiumRate:null;

  /* 1) 요율 변경이 성과에 준 영향 — "직전 프로모션에서는 X%였고 이번에는 Y%" 형태로 비교 대상을 문장에 항상 명시 */
  if(genPrevRate!=null && p.generalRate!=null && Math.abs(p.generalRate-genPrevRate)>=0.1){
    const dir=p.generalRate>genPrevRate?'상향':'하향';
    items.push(mkItem('plain', `직전 프로모션에서는 일반요율이 ${genPrevRate.toFixed(1)}%였고, 이번 프로모션에서는 ${p.generalRate.toFixed(1)}%로 ${dir} 조정되었습니다. 같은 기간 ROAS는 직전 대비 ${roasPChg!=null?fmtSigned(roasPChg):'—'} 변화했습니다.`));
  }
  if(premPrevRate!=null && p.premiumRate!=null && Math.abs(p.premiumRate-premPrevRate)>=0.1){
    const dir=p.premiumRate>premPrevRate?'상향':'하향';
    items.push(mkItem('plain', `직전 프로모션에서는 우수요율이 ${premPrevRate.toFixed(1)}%였고, 이번 프로모션에서는 ${p.premiumRate.toFixed(1)}%로 ${dir} 조정되었습니다.`));
  }
  if(curTier.general.n>0 && curTier.premium.n>0){
    const rg=affRoas(curTier.general), rp=affRoas(curTier.premium);
    if(rg>0 || rp>0){
      const better=rg>=rp?'일반':'우수', worse=better==='일반'?'우수':'일반';
      const tierGap=pctChangeSafe(better==='일반'?rg:rp, better==='일반'?rp:rg);
      items.push(mkItem('plain', `이번 프로모션은 <b>${better}요율</b> 그룹의 ROAS가 <b>${worse}요율</b> 그룹보다 ${tierGap!=null?Math.abs(tierGap).toFixed(1)+'%':''} 더 높게 나타났습니다.`));
    }
  }

  /* 2) 발생건수 증가 대비 수수료 증가가 적절했는지 (직전 대비 — ordP/feeP 모두 prev 기준으로만 계산됨) */
  if(ordP!=null && feeP!=null){
    const gap=feeP-ordP;
    if(gap>=10){
      items.push(mkItem('warn', `발생건수는 직전 대비 ${fmtSigned(ordP)} 변화한 반면 수수료는 직전 대비 ${fmtSigned(feeP)} 늘어, 건수 증가 대비 수수료 부담이 더 빠르게 증가했습니다.`));
    } else if(ordP>0){
      items.push(mkItem('good', `발생건수가 직전 대비 ${fmtSigned(ordP)} 늘었고 수수료는 직전 대비 ${fmtSigned(feeP)}로 비교적 효율적으로 성과가 확대되었습니다.`));
    }
  }

  /* 3) ROAS가 좋아졌는지 나빠졌는지 — 25.02x 같은 배수 표기 대신 변화율(%)만으로 서술 */
  if(roasPChg!=null){
    items.push(mkItem(roasPChg>=0?'good':'warn', `직전 대비 ROAS가 ${fmtSigned(roasPChg)} ${roasPChg>=0?'개선':'악화'}되었습니다.`));
  } else if(roasYChg!=null){
    items.push(mkItem(roasYChg>=0?'good':'warn', `전년 동일 프로모션 대비 ROAS가 ${fmtSigned(roasYChg)} ${roasYChg>=0?'개선':'악화'}되었습니다.`));
  }

  /* 4) 어필리에이트 효율이 가장 좋은 SKU (표본이 너무 적은 SKU는 제외) — 절대값 단일 지표라 비교 대상이 없으므로 "배"로 표기 */
  const eligible=skuRanking.filter(s=>s.n>=3);
  if(eligible.length){
    const byRoas=eligible.slice().sort((a,b)=>affRoas(b)-affRoas(a))[0];
    items.push(mkItem('good', `SKU 중 <b>${byRoas.sku}</b>가 가장 높은 ROAS(${affRoasPct(byRoas)})를 기록했습니다 (매출 ${f0(byRoas.rev)}엔 · ${byRoas.n}건).`));
  }
  if(skuRanking.length){
    const topRev=skuRanking[0];
    items.push(mkItem('plain', `매출 기준 최상위 SKU는 <b>${topRev.sku}</b>입니다 (매출 ${f0(topRev.rev)}엔 · ${topRev.n}건 · ROAS ${affRoasPct(topRev)}).`));
  }

  /* 5) 다음 프로모션 요율 추천 — 유지/상향/하향
     일반·우수 요율이 서로 반대 방향으로 바뀐 경우(예: 일반은 인하, 우수는 인상)를 rateUp/rateDown이
     동시에 true가 되는 것으로 방치하면 if/else 순서상 rateUp 분기만 타서 "요율을 상향했다"는
     한쪽만 반영한 문구가 나가 오해를 준다 — mixed로 분리해 두 방향 변경을 모두 알려준다. */
  let reco;
  const genChg=(genPrevRate!=null&&p.generalRate!=null)?p.generalRate-genPrevRate:null;
  const premChg=(premPrevRate!=null&&p.premiumRate!=null)?p.premiumRate-premPrevRate:null;
  const rateUp=(genChg!=null&&genChg>0)||(premChg!=null&&premChg>0);
  const rateDown=(genChg!=null&&genChg<0)||(premChg!=null&&premChg<0);
  const rateMixed=rateUp&&rateDown;
  if(roasPChg==null){
    reco=mkItem('plain', `직전 프로모션 데이터가 없어 요율 변경 효과를 비교하기 어렵습니다. 다음 회차 비교를 위해 현재 요율을 유지하며 데이터를 축적하는 것을 권장합니다.`);
  } else if(rateMixed){
    reco=mkItem(roasPChg>=0?'good':'warn', `일반요율과 우수요율이 직전 프로모션 대비 서로 다른 방향으로 조정되었습니다 (일반 ${genChg>0?'상향':'하향'}, 우수 ${premChg>0?'상향':'하향'}). 같은 기간 ROAS는 직전 대비 ${fmtSigned(roasPChg)} ${roasPChg>=0?'개선':'악화'}되었는데, 두 요율이 동시에 바뀌어 어느 쪽이 효과를 냈는지 구분하기 어렵습니다. 다음 프로모션에서는 한 번에 하나의 요율만 조정해 각각의 효과를 확인해보는 것을 권장합니다.`);
  } else if(rateUp && roasPChg<=-15){
    reco=mkItem('warn', `직전 프로모션 대비 요율을 상향했음에도 ROAS가 ${fmtSigned(roasPChg)} 악화되었습니다. 다음 프로모션에서는 요율을 <b>하향</b>하거나 이전 수준으로 되돌리는 것을 검토해보세요.`);
  } else if(rateUp && roasPChg>=0){
    reco=mkItem('good', `직전 프로모션 대비 요율을 상향했음에도 ROAS가 유지·개선되었습니다. 다음 프로모션에서도 현재 요율을 <b>유지</b>하거나, 발생건수 반응을 보며 소폭 <b>상향 테스트</b>를 고려해볼 수 있습니다.`);
  } else if(rateDown && roasPChg>=0){
    reco=mkItem('good', `직전 프로모션 대비 요율을 낮췄는데도 ROAS가 개선되었습니다. 현재 요율을 <b>유지</b>하는 것을 권장합니다.`);
  } else if(rateDown && roasPChg<0){
    reco=mkItem('warn', `직전 프로모션 대비 요율을 낮췄는데 ROAS도 함께 악화되었습니다. 요율 외 다른 요인(상품 구성·시즌성 등)도 함께 점검하고, 다음 프로모션에서는 요율을 <b>이전 수준으로 복원</b>하는 것을 검토해보세요.`);
  } else {
    reco=mkItem(roasPChg>=0?'good':'plain', `직전 프로모션 대비 요율 변경이 없었고 ROAS는 직전 대비 ${fmtSigned(roasPChg)} 변화했습니다. 다음 프로모션에서도 현재 요율 <b>유지</b>를 권장합니다.`);
  }
  items.push(reco);

  return '<div class="insight-wrap">'+items.map(it=>`<div class="insight-item${it.cls==='plain'?'':' '+it.cls}"><span class="ic">${it.icon}</span><span>${it.text}</span></div>`).join('')+'</div>';
}

/* ---- SKU 랭킹/상세 ---- */
function affSkuRanking(rows, prevRows, yoyRows, topN){
  return affBySku(rows).sort((a,b)=>b.rev-a.rev).slice(0, topN||30).map(s=>({
    ...s,
    prev:affSum(prevRows.filter(r=>r.sku===s.sku)),
    yoy:affSum(yoyRows.filter(r=>r.sku===s.sku)),
  }));
}
function renderAffSkuRankingTable(rows, prevRows, yoyRows){
  const el=document.getElementById('af-sku-rank'); if(!el) return [];
  const list=affSkuRanking(rows, prevRows, yoyRows, 30);
  let t='<thead><tr><th>순위</th><th>SKU</th><th>매출</th><th>발생건수</th><th>수수료</th><th>광고비율</th><th>ROAS</th><th>매출 직전비</th><th>매출 전년비</th></tr></thead><tbody>';
  list.forEach((s,i)=>{
    const dP=delta(s.rev, s.prev.rev, prevRows.length>0);
    const dY=delta(s.rev, s.yoy.rev, yoyRows.length>0);
    t+=`<tr><td>${i+1}</td><td>${s.sku}</td><td>${f0(s.rev)}</td><td>${f0(s.n)}</td><td>${f0(s.fee)}</td><td>${fp1(affAdRatio(s))}</td><td>${affRoasPct(s)}</td><td class="${dP.c}">${dP.t}</td><td class="${dY.c}">${dY.t}</td></tr>`;
  });
  el.innerHTML=t+'</tbody>';
  return list;
}
function renderAffSkuDetail(rows){
  const sel=document.getElementById('af-sku-detail-select'), box=document.getElementById('af-sku-detail-kpi');
  if(!sel||!box) return;
  const list=affBySku(rows).sort((a,b)=>b.rev-a.rev);
  const keep=(sel.value&&list.some(s=>s.sku===sel.value))?sel.value:(list[0]?list[0].sku:'');
  fillSelect(sel, list.map(s=>({v:s.sku,t:s.sku})), keep);
  const one=list.find(s=>s.sku===keep)||{rev:0,fee:0,n:0};
  const M=[
    {l:'매출', v:fy(one.rev)}, {l:'발생건수', v:f0(one.n)}, {l:'수수료', v:fy(one.fee)},
    {l:'광고비율', v:fp1(affAdRatio(one))}, {l:'ROAS', v:affRoasPct(one)},
  ];
  box.innerHTML=M.map(m=>`<div class="kpi"><div class="lbl">${m.l}</div><div class="val">${m.v}</div></div>`).join('');
}

/* ---- 일반/우수 요율 비교 표 ---- */
function renderAffTierTable(p, curTier, totalRev){
  const el=document.getElementById('af-rate-tbl'); if(!el) return;
  const rows=[{l:'일반', rate:p.generalRate, a:curTier.general},{l:'우수', rate:p.premiumRate, a:curTier.premium}];
  if(curTier.other.n>0) rows.push({l:'기타(기본 제휴요율)', rate:null, a:curTier.other});
  let t='<thead><tr><th>구분</th><th>요율</th><th>매출</th><th>매출비중</th><th>발생건수</th><th>수수료</th><th>ROAS</th></tr></thead><tbody>';
  rows.forEach(r=>{
    t+=`<tr><td>${r.l}</td><td>${r.rate!=null?r.rate.toFixed(1)+'%':'—'}</td><td>${f0(r.a.rev)}</td><td>${totalRev?fp0(r.a.rev/totalRev):'—'}</td><td>${f0(r.a.n)}</td><td>${f0(r.a.fee)}</td><td>${affRoasPct(r.a)}</td></tr>`;
  });
  el.innerHTML=t+'</tbody>';
}

/* ---- 전체 프로모션 현황 요약 (신규) — #af-summary-year로 고른 연도만 표시한다(전체 프로모션/연도
   선택(af-year/af-promo)과는 독립적인 상태). 일반/우수 2개 구분만 표시(기타는 상세 화면에만 유지).
   기존 renderAffTierTable과 동일한 집계 함수(affRange/affSum/affSplitByTier)를 그대로 재사용한다. */
function renderAffSummaryTable(){
  const el=document.getElementById('af-summary-tbl'); if(!el) return;
  let t='<thead><tr><th>프로모션</th><th style="text-align:center">구분</th><th>요율</th><th>매출</th><th>매출비중</th><th>발생건수</th><th>수수료</th><th>ROAS</th></tr></thead><tbody>';
  affPromosSorted().filter(p=>!afSummaryYear || ('20'+p.year)===afSummaryYear).forEach(p=>{
    const rows=affRange(p.start,p.end); if(!rows.length) return;
    const totalRev=affSum(rows).rev;
    const tier=affSplitByTier(rows,p);
    const parts=[{l:'일반',rate:p.generalRate,a:tier.general},{l:'우수',rate:p.premiumRate,a:tier.premium}];
    parts.forEach((r,i)=>{
      t+=`<tr>${i===0?`<td rowspan="${parts.length}">${p.label}</td>`:''}<td style="text-align:center">${r.l}</td><td>${r.rate!=null?r.rate.toFixed(1)+'%':'—'}</td><td>${f0(r.a.rev)}</td><td>${totalRev?fp0(r.a.rev/totalRev):'—'}</td><td>${f0(r.a.n)}</td><td>${f0(r.a.fee)}</td><td>${affRoasPct(r.a)}</td></tr>`;
    });
  });
  el.innerHTML=t+'</tbody>';
}

/* ---- 메인 렌더 ---- */
function renderAF(){
  const kpiBox=document.getElementById('af-kpi'); if(!kpiBox) return;
  renderAffSummaryTable();
  renderMemoBox('affiliate', memoCtxAF());
  const p=affPromoById(affState.promoId);
  if(!p){
    kpiBox.innerHTML='<div class="muted-note">어필리에이트_RAW 시트에서 데이터를 아직 불러오지 못했습니다. (P~Z열 프로모션 설정 또는 A~N열 RAW 확인 필요)</div>';
    ['af-ai','af-rate-tbl','af-sku-rank'].forEach(id=>{const e=document.getElementById(id); if(e) e.innerHTML='';});
    if(document.getElementById('af-band')) document.getElementById('af-band').innerHTML='';
    if(document.getElementById('af-sku-detail-kpi')) document.getElementById('af-sku-detail-kpi').innerHTML='';
    return;
  }
  if(document.getElementById('af-period')) document.getElementById('af-period').textContent=`${p.start} ~ ${p.end} (${promoLen(p)}일)`;
  const prevPromo=p.prevId?affPromoById(p.prevId):null;
  if(document.getElementById('af-band')) document.getElementById('af-band').innerHTML=bandHTML([
    {k:'금번', s:p.start, e:p.end},
    {k:'직전', s:p.prevStart, e:p.prevEnd, note:p.prevId?affPromoLabelShort(p.prevId):''},
    {k:'전년', s:p.yoyStart, e:p.yoyEnd, note:p.yoyId?affPromoLabelShort(p.yoyId):''},
  ]);

  const curRows=affRange(p.start,p.end);
  const prevRows=(p.prevStart&&p.prevEnd)?affRange(p.prevStart,p.prevEnd):[];
  const yoyRows=(p.yoyStart&&p.yoyEnd)?affRange(p.yoyStart,p.yoyEnd):[];
  const cur=affSum(curRows), prev=prevRows.length?affSum(prevRows):null, yoy=yoyRows.length?affSum(yoyRows):null;
  const curTier=affSplitByTier(curRows,p);

  const M=[
    {l:'매출', f:fy, g:a=>a.rev},
    {l:'발생건수', f:f0, g:a=>a.n},
    {l:'수수료', f:fy, g:a=>a.fee},
    {l:'광고비율', f:fp1, g:affAdRatio, pct:true},
    {l:'ROAS', f:v=>f0(v*100)+'%', g:affRoas},
    {l:'건당 수수료', f:fy, g:affFeePerN},
  ];
  let kpiHtml=M.map(m=>{
    const c=m.g(cur);
    const dPrev=m.pct? deltaP(c, prev?m.g(prev):null, !!prev) : delta(c, prev?m.g(prev):null, !!prev);
    const dYoy=m.pct? deltaP(c, yoy?m.g(yoy):null, !!yoy) : delta(c, yoy?m.g(yoy):null, !!yoy);
    return `<div class="kpi"><div class="lbl">${m.l}</div><div class="val">${m.f(c)}</div>
    <div class="dl"><span>직전비 <span class="${dPrev.c}">${dPrev.t}</span></span><span>전년비 <span class="${dYoy.c}">${dYoy.t}</span></span></div></div>`;
  }).join('');
  const yoyPromo=p.yoyId?affPromoById(p.yoyId):null;
  [['일반요율','generalRate'],['우수요율','premiumRate']].forEach(([lbl,key])=>{
    const c=p[key], pv=prevPromo?prevPromo[key]:null, yv=yoyPromo?yoyPromo[key]:null;
    // deltaP는 "비율(0~1)의 %p차이"를 계산하는 헬퍼라 내부에서 ×100을 한 번 하므로,
    // 이미 %단위 숫자인 요율(예:13)을 그대로 넣으면 ×100이 중복 적용돼 값이 100배로 뻥튀기된다.
    // 반드시 100으로 나눠 비율(0.13)로 맞춰서 넘겨야 한다.
    const cFrac=c!=null?c/100:null, pvFrac=pv!=null?pv/100:null, yvFrac=yv!=null?yv/100:null;
    const dPrev=deltaP(cFrac,pvFrac,pv!=null&&c!=null), dYoy=deltaP(cFrac,yvFrac,yv!=null&&c!=null);
    kpiHtml+=`<div class="kpi"><div class="lbl">${lbl}</div><div class="val">${c!=null?c.toFixed(1)+'%':'—'}</div>
    <div class="dl"><span>직전비 <span class="${dPrev.c}">${dPrev.t}</span></span><span>전년비 <span class="${dYoy.c}">${dYoy.t}</span></span></div></div>`;
  });
  kpiBox.innerHTML=kpiHtml;

  renderAffTierTable(p, curTier, cur.rev);

  const rankList=renderAffSkuRankingTable(curRows, prevRows, yoyRows);
  renderAffSkuDetail(curRows);

  if(document.getElementById('af-ai')) document.getElementById('af-ai').innerHTML=renderAffiliateInsightHTML(p, prevPromo, cur, prev, yoy, curTier, rankList);

  const chartEl=document.getElementById('af-chart');
  if(chartEl){
    const ML=Math.max(promoLen(p), p.prevStart?periodLen(p.prevStart,p.prevEnd):0, p.yoyStart?periodLen(p.yoyStart,p.yoyEnd):0);
    const dm=affDayMapBuild();
    const metricSel=document.getElementById('af-metric');
    const metricKey={'매출':'rev','발생건수':'n','수수료':'fee'}[(metricSel&&metricSel.value)||'매출'];
    const labels=Array.from({length:ML},(_,k)=>(k+1)+'일차');
    const seriesCur=affElapsedSeries(p.start, promoLen(p), ML, r=>r[metricKey], dm);
    const seriesPrev=p.prevStart? affElapsedSeries(p.prevStart, periodLen(p.prevStart,p.prevEnd), ML, r=>r[metricKey], dm) : Array(ML).fill(null);
    const seriesYoy=p.yoyStart? affElapsedSeries(p.yoyStart, periodLen(p.yoyStart,p.yoyEnd), ML, r=>r[metricKey], dm) : Array(ML).fill(null);
    setChart('af-chart',{type:'line',data:{labels,datasets:[
      {label:'금번',data:seriesCur,borderColor:COLORS[0],pointBackgroundColor:COLORS[0],tension:.3,spanGaps:true},
      {label:'직전',data:seriesPrev,borderColor:COLORS[1],pointBackgroundColor:COLORS[1],borderDash:[6,4],tension:.3,spanGaps:true},
      {label:'전년',data:seriesYoy,borderColor:COLORS[2],pointBackgroundColor:COLORS[2],borderDash:[2,3],tension:.3,spanGaps:true},
    ]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},
      plugins:{legend:{display:false},tooltip:{mode:'index',intersect:false,itemSort:(a,b)=>b.parsed.y-a.parsed.y,callbacks:{label:c=>c.parsed.y==null?null:c.dataset.label+': '+c.parsed.y.toLocaleString('en-US')}}},
      scales:{y:{ticks:{callback:v=>v.toLocaleString('en-US')}}}}});
    if(document.getElementById('af-chart-lg')) document.getElementById('af-chart-lg').innerHTML=['금번','직전','전년'].map((l,i)=>`<span><i style="border-color:${COLORS[i]}"></i>${l}</span>`).join('');
  }
}

if(document.getElementById('af-metric')) document.getElementById('af-metric').onchange=renderAF;
if(document.getElementById('af-sku-detail-select')) document.getElementById('af-sku-detail-select').onchange=renderAF;

/* ---- 데이터 로딩 확장: 기존(및 유입 분석이 이미 감싼) loadLive()는 그대로 두고, 한 번 더 감싸서 affiliate만 채운다 ---- */
