/* ============================================================
   신규 기능(어필리에이트 분석) 끝
   ============================================================ */

/* ============================================================
   신규 기능: 탭 ⑧ 쿠폰 분석 (기존 코드/DATA/탭·함수는 전혀 수정하지 않고 전부 새로 추가
   — 단, renderTab() 배열에 renderCoupon 등록은 탭 ⑦ 추가 때와 동일하게 최소 1줄 필요)
   데이터 출처: data.json의 sheets.coupon (시트명: 쿠폰) · A~O열
     A=프로모션명 B=연도 C=월 D=쿠폰구분 E=금액허들 F=할인율 G=발행수 H=사용수
     I=다운로드수 J=CVR K=시작일 L=시작시간 M=종료일 N=종료시간 O=비고
   ============================================================ */

if(!DATA.coupon) DATA.coupon={rows:[], promos:[]};

const CP_MIN_SAMPLE=5; /* AI 분석에서 표본이 너무 적은 쿠폰(발행수 미달)을 "최고/최저" 판정에서 제외하기 위한 최소 발행수 */

/* 할인율(F열) 파싱: 퍼센트("25%")와 정액("200엔")이 한 컬럼에 섞여 들어오므로, 원본 표기를 최대한
   그대로 살린다 — "%"가 있으면 그 숫자만 반올림해 퍼센트로, 숫자가 아닌 텍스트(예: "200엔")는
   원본 그대로 표시하고 할인율 기반 순위/평균 계산에서는 제외한다(pct:null). 소수점이 있는 시트
   포맷(예: 0.25 = 25%)만 100배해 반올림한다 — "200"처럼 단위 없는 순수 숫자는 기존과 동일하게
   퍼센트로 취급해 하위 호환을 유지한다. */
function parseCouponDiscount(cell){
  const text=nstr(cell);
  if(text==='') return {pct:null, display:'—'};
  if(/%/.test(text)){
    const n=num(text);
    return isFinite(n)? {pct:n, display:Math.round(n)+'%'} : {pct:null, display:text};
  }
  if(!/^-?[\d,.]+$/.test(text)) return {pct:null, display:text}; // 정액 할인(예: "200엔") 등 — 원본 그대로
  const n=Number(text.replace(/,/g,''));
  if(!isFinite(n)) return {pct:null, display:text};
  const pct=(n>0&&n<1)?n*100:n;
  return {pct, display:Math.round(pct)+'%'};
}

/* 쿠폰_RAW 시트 원본 셀 배열 → {rows, promos}. 프로모션 단위(연도+월+프로모션명)로 그룹핑해
   시작일=그룹 내 최소 K열, 종료일=그룹 내 최대 M열로 프로모션 기간을 만들고, 어필리에이트 탭과
   동일하게 derivePrevYoy()로 직전·전년(동일 프로모션명 기준)을 자동 매칭한다. */
function parseCouponSheet(cells){
  const all=cellsOf(cells);
  const rows=[];
  all.forEach(r=>{
    const nm=nstr(r[0]); if(!nm||nm==='프로모션명') return;
    const start=ndate(r[10]); if(!start) return;
    const yy=String(Math.round(nnum(r[1]))).slice(-2);
    const mm=String(Math.round(nnum(r[2])));
    const issuedText=nstr(r[6]);
    const disc=parseCouponDiscount(r[5]);
    rows.push({
      promoId:`${yy}-${mm}-${nm}`, promoName:nm, year:yy, month:mm,
      kind:nstr(r[3])||'(미상)',
      hurdle:nnum(r[4]),
      discountPct:disc.pct, discountDisplay:disc.display,
      issued:nnum(r[6]), issuedText, issuedUnlimited:issuedText==='무제한',
      used:nnum(r[7]), downloads:nnum(r[8]),
      cvr:affPctScale(nnum(r[9])),
      start, startTime:nstr(r[11]),
      end:ndate(r[12])||start, endTime:nstr(r[13]),
      note:nstr(r[14]),
    });
  });
  const pm={};
  rows.forEach(r=>{
    const cur=pm[r.promoId];
    if(!cur) pm[r.promoId]={id:r.promoId, label:`${r.year}년 ${r.month}월 ${r.promoName}`, type:r.promoName, year:r.year, start:r.start, end:r.end};
    else { if(r.start<cur.start) cur.start=r.start; if(r.end>cur.end) cur.end=r.end; }
  });
  const promos=Object.values(pm);
  derivePrevYoy(promos);
  return {rows, promos};
}

/* ---- 집계 헬퍼 ---- */
function couponSum(rows){
  let issued=0,used=0,downloads=0,discSum=0,discN=0,cvrSum=0,cvrN=0,hurdleSum=0,hurdleN=0;
  rows.forEach(r=>{
    issued+=r.issued; used+=r.used; downloads+=r.downloads;
    if(r.discountPct!=null){discSum+=r.discountPct;discN++;}
    if(r.cvr!=null){cvrSum+=r.cvr;cvrN++;}
    if(r.hurdle!=null){hurdleSum+=r.hurdle;hurdleN++;}
  });
  return {
    n:rows.length, issued, used, downloads,
    avgDiscount:discN?discSum/discN:0,
    avgCvr:cvrN?cvrSum/cvrN:0,
    avgHurdle:hurdleN?hurdleSum/hurdleN:0,
  };
}
/* 발행수가 "무제한"인 쿠폰(주로 SHOP 기본 쿠폰)은 사용수÷발행수를 계산할 수 없으므로 null을 반환한다.
   실제로 발행수가 0(=무제한이 아니라 진짜 0건)인 기존 케이스는 이전과 동일하게 0을 반환해 그 외
   동작에는 영향이 없다. */
const couponUseRate=r=>r.issuedUnlimited? null : (r.issued? r.used/r.issued : 0);           // 사용률 = 사용수÷발행수
const couponDlRate=r=>r.issuedUnlimited? null : (r.issued? r.downloads/r.issued : 0);       // 발행→다운로드 도달률
const couponKindLabel=r=>r.note? `${r.kind} (${r.note})` : r.kind; // 비고(O열)에 값이 있으면 쿠폰구분과 무관하게 항상 괄호로 붙여 표시
const couponSortIssued=r=>r.issuedUnlimited? Infinity : r.issued; // "발행수 많은 순" 정렬 시 무제한 쿠폰이 0건 취급되어 맨 아래로 밀리지 않도록
function couponIssuePeriodDays(r){ if(!r.start||!r.end) return null; return Math.round((new Date(r.end+'T00:00:00Z')-new Date(r.start+'T00:00:00Z'))/86400000)+1; }

/* ---- 프로모션/쿠폰구분 드롭다운 (연도→프로모션→쿠폰구분, 전부 시트 원본에서 자동 생성) ---- */
/* 정렬 기준은 쿠폰 시트 자체의 시작일(개별 쿠폰 발행일 — 프로모션 공식 기간과 다를 수 있음)이 아니라,
   프로모션_항목 시트의 공식 시작일(DATA.promos, promoById)을 우선 사용한다 — id 포맷이 동일(`yy-mm-이름`)
   하므로 그대로 조회 가능. 매칭되는 프로모션_항목 행이 없는 예외 케이스만 기존 방식(coupon.start)으로 폴백. */
const couponPromosSorted=()=>(DATA.coupon.promos||[]).slice().sort((a,b)=>{
  const sa=(promoById(a.id)||{}).start||a.start, sb=(promoById(b.id)||{}).start||b.start;
  return sb.localeCompare(sa);
});
const couponPromoById=id=>(DATA.coupon.promos||[]).find(p=>p.id===id);
const couponPromoLabelShort=id=>{const q=couponPromoById(id); return q? (q.year+'.'+(+q.start.slice(5,7))+' '+q.type) : '';};

let cpState={year:'', promoId:'', kind:'__ALL__'};
/* 쿠폰구분 드롭다운은 D열 고유값을 하드코딩 없이 매번 읽어 생성한다.
   범위는 "현재 선택된 프로모션 내에 실제로 존재하는 값"으로 한정해, 그 프로모션에 없는
   구분이 목록에 나타나 혼란을 주지 않게 한다 (프로모션을 바꾸면 목록도 함께 갱신됨). */
function refreshCouponKindOptions(){
  const kindSel=document.getElementById('cp-kind'); if(!kindSel) return;
  const kinds=[...new Set(DATA.coupon.rows.filter(r=>r.promoId===cpState.promoId).map(r=>r.kind))];
  const keepK=(cpState.kind&&(cpState.kind==='__ALL__'||kinds.includes(cpState.kind)))?cpState.kind:'__ALL__';
  fillSelect(kindSel, [{v:'__ALL__',t:'전체'}].concat(kinds.map(k=>({v:k,t:k}))), keepK);
  cpState.kind=keepK;
}
function initCouponControls(){
  const yearSel=document.getElementById('cp-year'), promoSel=document.getElementById('cp-promo');
  if(!yearSel||!promoSel) return;
  const years=[...new Set(couponPromosSorted().map(p=>'20'+p.year))].sort().reverse();
  const keepY=(cpState.year&&years.includes(cpState.year))?cpState.year:(years[0]||'');
  fillSelect(yearSel, years.map(y=>({v:y,t:y+'년'})), keepY);
  cpState.year=keepY;
  const list=couponPromosSorted().filter(p=>('20'+p.year)===cpState.year);
  const keepP=(cpState.promoId&&list.some(p=>p.id===cpState.promoId))?cpState.promoId:(list[0]?list[0].id:'');
  fillSelect(promoSel, list.map(p=>({v:p.id,t:p.label})), keepP);
  cpState.promoId=keepP;
  refreshCouponKindOptions();
  yearSel.onchange=function(){
    cpState.year=yearSel.value;
    const l=couponPromosSorted().filter(p=>('20'+p.year)===cpState.year);
    cpState.promoId=l[0]?l[0].id:'';
    fillSelect(promoSel, l.map(p=>({v:p.id,t:p.label})), cpState.promoId);
    refreshCouponKindOptions();
    renderCoupon();
  };
  promoSel.onchange=function(){ cpState.promoId=promoSel.value; refreshCouponKindOptions(); renderCoupon(); };
  const kindSel=document.getElementById('cp-kind');
  if(kindSel) kindSel.onchange=function(){ cpState.kind=kindSel.value; renderCoupon(); };
}

/* ---- AI 분석 (규칙 기반, 외부 API 호출 없음 — 어필리에이트 탭과 동일한 방식) ---- */
function renderCouponInsightHTML(p, cur, prev, yoy, curRows){
  const items=[];
  if(!curRows.length){
    items.push(mkItem('plain','이번 프로모션에 집계된 쿠폰 데이터가 없습니다.'));
    return '<div class="insight-wrap">'+items.map(it=>`<div class="insight-item${it.cls==='plain'?'':' '+it.cls}"><span class="ic">${it.icon}</span><span>${it.text}</span></div>`).join('')+'</div>';
  }
  const withRate=curRows.map(r=>({r, useRate:couponUseRate(r), dlRate:couponDlRate(r)}));
  /* 발행수가 "무제한"인 쿠폰(주로 SHOP 기본 쿠폰)은 사용률·도달률 계산에서만 제외하고,
     다운로드수·사용수·CVR 등 나머지 분석(아래 4번 등)에는 그대로 포함시킨다. */
  const rateable=withRate.filter(x=>x.useRate!=null);
  const avgUseRate=rateable.length? rateable.reduce((s,x)=>s+x.useRate,0)/rateable.length : 0;
  const avgDlRate=rateable.length? rateable.reduce((s,x)=>s+x.dlRate,0)/rateable.length : 0;
  const eligible=rateable.filter(x=>x.r.issued>=CP_MIN_SAMPLE);
  const pool=eligible.length?eligible:rateable;

  /* 1) 가장 효율 좋은 쿠폰 (사용률 기준) */
  const bestUse=pool.slice().sort((a,b)=>b.useRate-a.useRate)[0];
  if(bestUse) items.push(mkItem('good', `<b>${couponKindLabel(bestUse.r)}</b> 쿠폰이 가장 높은 사용률(${fp1(bestUse.useRate)})을 기록해 이번 프로모션에서 가장 효율이 좋았습니다 (발행 ${f0(bestUse.r.issued)}건 · 사용 ${f0(bestUse.r.used)}건).`));

  /* 2) 다운로드는 많지만 실제 사용률이 낮은 쿠폰 (무제한 발행 쿠폰은 사용률 산정 불가하므로 제외) */
  const highDl=withRate.slice().sort((a,b)=>b.r.downloads-a.r.downloads).slice(0, Math.max(1, Math.ceil(withRate.length/2)));
  const lowUseAmongHighDl=highDl.filter(x=>x.useRate!=null&&x.useRate<avgUseRate*0.7).sort((a,b)=>a.useRate-b.useRate)[0];
  if(lowUseAmongHighDl) items.push(mkItem('warn', `<b>${couponKindLabel(lowUseAmongHighDl.r)}</b> 쿠폰은 다운로드가 ${f0(lowUseAmongHighDl.r.downloads)}건으로 많은 편이지만 실제 사용률은 ${fp1(lowUseAmongHighDl.useRate)}에 그쳐, 다운로드 대비 실사용 전환이 저조합니다.`));

  /* 3) 할인율이 높은데 성과(사용률)가 낮은 쿠폰 (정액 할인·무제한 발행 쿠폰은 제외) */
  const discSorted=withRate.filter(x=>x.r.discountPct!=null).sort((a,b)=>b.r.discountPct-a.r.discountPct);
  const highDiscLowPerf=discSorted.find(x=>x.useRate!=null&&x.useRate<avgUseRate*0.7);
  if(highDiscLowPerf) items.push(mkItem('warn', `<b>${couponKindLabel(highDiscLowPerf.r)}</b> 쿠폰은 할인율이 ${highDiscLowPerf.r.discountPct.toFixed(1)}%로 높은 편인데도 사용률은 ${fp1(highDiscLowPerf.useRate)}로 평균(${fp1(avgUseRate)}) 대비 낮아, 할인폭 대비 효율이 아쉽습니다.`));

  /* 4) 가장 많이 사용된 쿠폰 — 무제한 발행 쿠폰도 포함해 전체 curRows 기준으로 판정 */
  const mostUsed=withRate.slice().sort((a,b)=>b.r.used-a.r.used)[0];
  if(mostUsed) items.push(mkItem('plain', `실제 사용 건수 기준으로는 <b>${couponKindLabel(mostUsed.r)}</b> 쿠폰이 가장 많이 사용되었습니다 (${f0(mostUsed.r.used)}건).`));

  /* 보너스) 발행 대비 다운로드율이 낮은 쿠폰 — 노출/도달(인지) 문제 가능성 (무제한 발행 쿠폰은 제외) */
  const lowDlRate=pool.slice().sort((a,b)=>a.dlRate-b.dlRate)[0];
  if(lowDlRate && lowDlRate.dlRate<avgDlRate*0.6) items.push(mkItem('warn', `<b>${couponKindLabel(lowDlRate.r)}</b> 쿠폰은 발행 대비 다운로드율이 ${fp1(lowDlRate.dlRate)}로 평균(${fp1(avgDlRate)}) 대비 낮습니다. 노출 위치나 안내 방식을 점검해볼 필요가 있습니다.`));

  /* 5) 전체 사용률의 직전·전년 대비 변화 */
  if(prev && prev.issued){
    const chg=pctChangeSafe(couponUseRate({issued:cur.issued,used:cur.used}), couponUseRate({issued:prev.issued,used:prev.used}));
    if(chg!=null) items.push(mkItem(chg>=0?'good':'warn', `전체 쿠폰 사용률이 직전 프로모션 대비 ${fmtSigned(chg)} ${chg>=0?'개선':'악화'}되었습니다 (${fp1(couponUseRate({issued:prev.issued,used:prev.used}))} → ${fp1(couponUseRate({issued:cur.issued,used:cur.used}))}).`));
  } else if(yoy && yoy.issued){
    const chg=pctChangeSafe(couponUseRate({issued:cur.issued,used:cur.used}), couponUseRate({issued:yoy.issued,used:yoy.used}));
    if(chg!=null) items.push(mkItem(chg>=0?'good':'warn', `전체 쿠폰 사용률이 전년 동일 프로모션 대비 ${fmtSigned(chg)} ${chg>=0?'개선':'악화'}되었습니다 (${fp1(couponUseRate({issued:yoy.issued,used:yoy.used}))} → ${fp1(couponUseRate({issued:cur.issued,used:cur.used}))}).`));
  }

  /* 6) 다음 프로모션 추천 — 유지/축소/확대 */
  const worstUse=pool.slice().sort((a,b)=>a.useRate-b.useRate)[0];
  if(bestUse) items.push(mkItem('good', `다음 프로모션에서는 <b>${couponKindLabel(bestUse.r)}</b> 쿠폰의 발행 규모 확대를 검토해볼 수 있습니다 (사용률 ${fp1(bestUse.useRate)}로 가장 우수).`));
  if(worstUse && bestUse && worstUse.r.kind!==bestUse.r.kind && worstUse.useRate<avgUseRate*0.5) items.push(mkItem('warn', `<b>${couponKindLabel(worstUse.r)}</b> 쿠폰은 사용률이 ${fp1(worstUse.useRate)}로 저조해, 다음 프로모션에서는 발행 규모 축소나 허들·할인율 조건 재검토를 권장합니다.`));

  return '<div class="insight-wrap">'+items.map(it=>`<div class="insight-item${it.cls==='plain'?'':' '+it.cls}"><span class="ic">${it.icon}</span><span>${it.text}</span></div>`).join('')+'</div>';
}

/* ---- 쿠폰 상세 테이블 (발행수 DESC · 무제한 발행 쿠폰은 최상단) ---- */
function renderCouponTable(rows){
  const el=document.getElementById('cp-tbl'); if(!el) return;
  const list=rows.slice().sort((a,b)=>couponSortIssued(b)-couponSortIssued(a));
  let t='<thead><tr><th>쿠폰구분</th><th>금액 허들</th><th>할인율</th><th>발행수</th><th>사용수</th><th>미사용수</th><th>다운로드수</th><th>CVR</th><th>사용률</th><th>시작일</th><th>시작시간</th><th>종료일</th><th>종료시간</th><th>발행기간</th></tr></thead><tbody>';
  list.forEach(r=>{
    const issuedCell=r.issuedUnlimited? (r.issuedText||'무제한') : f0(r.issued);
    const unusedCell=r.issuedUnlimited? '-' : f0(r.issued-r.used);
    const useRateCell=r.issuedUnlimited? '-' : fp1(couponUseRate(r));
    const days=couponIssuePeriodDays(r);
    t+=`<tr><td>${couponKindLabel(r)}</td><td>${fy(r.hurdle)}</td><td>${r.discountDisplay||'—'}</td><td>${issuedCell}</td><td>${f0(r.used)}</td><td>${unusedCell}</td><td>${f0(r.downloads)}</td><td>${r.cvr!=null?r.cvr.toFixed(1)+'%':'—'}</td><td>${useRateCell}</td><td>${r.start||'—'}</td><td>${r.startTime||'—'}</td><td>${r.end||'—'}</td><td>${r.endTime||'—'}</td><td>${days!=null?days+'일':'—'}</td></tr>`;
  });
  el.innerHTML=t+'</tbody>';
}

/* ---- 비교 차트 ① 발행/사용 ② CVR·사용률 (쿠폰구분 필터가 적용된 rows 기준, 발행수 DESC 정렬)
   CVR과 사용률은 둘 다 %지표라 별도 차트로 나누면 중복돼 보이므로 하나의 차트에 묶어 직접 비교한다.
   사용률은 발행수가 "무제한"인 쿠폰에서는 계산할 수 없어 null(빈 막대)로 표시된다. ---- */
function renderCouponCharts(rows){
  const list=rows.slice().sort((a,b)=>couponSortIssued(b)-couponSortIssued(a));
  const labels=list.map(r=>couponKindLabel(r));
  if(document.getElementById('cp-chart-iss')) setChart('cp-chart-iss',{type:'bar',
    data:{labels,datasets:[
      {label:'발행수',data:list.map(r=>r.issuedUnlimited?null:r.issued),backgroundColor:COLORS[0]},
      {label:'사용수',data:list.map(r=>r.used),backgroundColor:COLORS[2]},
    ]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,position:'top'},tooltip:{callbacks:{label:c=>c.dataset.label+': '+(c.parsed.y==null?'무제한':c.parsed.y.toLocaleString('en-US'))}}},
      scales:{y:{ticks:{callback:v=>v.toLocaleString('en-US')}}}}});
  if(document.getElementById('cp-chart-cvr')) setChart('cp-chart-cvr',{type:'bar',
    data:{labels,datasets:[
      {label:'CVR',data:list.map(r=>r.cvr||0),backgroundColor:COLORS[1]},
      {label:'사용률',data:list.map(r=>{const u=couponUseRate(r); return u==null?null:u*100;}),backgroundColor:COLORS[3]},
    ]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,position:'top'},tooltip:{callbacks:{label:c=>c.dataset.label+': '+(c.parsed.y==null?'—(무제한)':c.parsed.y.toFixed(1)+'%')}}},
      scales:{y:{ticks:{callback:v=>v+'%'}}}}});
}

/* ---- 메인 렌더 ---- */
function renderCoupon(){
  const kpiBox=document.getElementById('cp-kpi'); if(!kpiBox) return;
  renderMemoBox('coupon', memoCtxCP());
  const p=couponPromoById(cpState.promoId);
  if(!p){
    kpiBox.innerHTML='<div class="muted-note">쿠폰 시트에서 데이터를 아직 불러오지 못했습니다. (A~O열 확인 필요)</div>';
    ['cp-ai','cp-tbl'].forEach(id=>{const e=document.getElementById(id); if(e) e.innerHTML='';});
    if(document.getElementById('cp-band')) document.getElementById('cp-band').innerHTML='';
    if(document.getElementById('cp-chart-iss')&&charts['cp-chart-iss']){charts['cp-chart-iss'].destroy();delete charts['cp-chart-iss'];}
    if(document.getElementById('cp-chart-cvr')&&charts['cp-chart-cvr']){charts['cp-chart-cvr'].destroy();delete charts['cp-chart-cvr'];}
    return;
  }
  if(document.getElementById('cp-period')) document.getElementById('cp-period').textContent=`${p.start} ~ ${p.end} (${promoLen(p)}일)`;
  const prevPromo=p.prevId?couponPromoById(p.prevId):null;
  const yoyPromo=p.yoyId?couponPromoById(p.yoyId):null;
  if(document.getElementById('cp-band')) document.getElementById('cp-band').innerHTML=bandHTML([
    {k:'금번', s:p.start, e:p.end},
    {k:'직전', s:p.prevStart, e:p.prevEnd, note:p.prevId?couponPromoLabelShort(p.prevId):''},
    {k:'전년', s:p.yoyStart, e:p.yoyEnd, note:p.yoyId?couponPromoLabelShort(p.yoyId):''},
  ]);

  const kind=(cpState.kind&&cpState.kind!=='__ALL__')?cpState.kind:null;
  const rowsOf=promoId=>DATA.coupon.rows.filter(r=>r.promoId===promoId&&(!kind||r.kind===kind));
  const curRows=rowsOf(p.id);
  const prevRows=prevPromo?rowsOf(prevPromo.id):[];
  const yoyRows=yoyPromo?rowsOf(yoyPromo.id):[];
  const cur=couponSum(curRows), prev=prevRows.length?couponSum(prevRows):null, yoy=yoyRows.length?couponSum(yoyRows):null;

  const M=[
    {l:'쿠폰 종류 수', f:f0, g:a=>a.n},
    {l:'총 발행수', f:f0, g:a=>a.issued},
    {l:'총 사용수', f:f0, g:a=>a.used},
    {l:'총 다운로드수', f:f0, g:a=>a.downloads},
    {l:'평균 할인율', f:fp1, g:a=>a.avgDiscount/100, pct:true},
    {l:'평균 CVR', f:fp1, g:a=>a.avgCvr/100, pct:true},
    {l:'평균 금액 허들', f:fy, g:a=>a.avgHurdle},
  ];
  kpiBox.innerHTML=M.map(m=>{
    const c=m.g(cur);
    const dPrev=m.pct? deltaP(c, prev?m.g(prev):null, !!prev) : delta(c, prev?m.g(prev):null, !!prev);
    const dYoy=m.pct? deltaP(c, yoy?m.g(yoy):null, !!yoy) : delta(c, yoy?m.g(yoy):null, !!yoy);
    return `<div class="kpi"><div class="lbl">${m.l}</div><div class="val">${m.f(c)}</div>
    <div class="dl"><span>직전비 <span class="${dPrev.c}">${dPrev.t}</span></span><span>전년비 <span class="${dYoy.c}">${dYoy.t}</span></span></div></div>`;
  }).join('');

  renderCouponTable(curRows);
  renderCouponCharts(curRows);
  if(document.getElementById('cp-ai')) document.getElementById('cp-ai').innerHTML=renderCouponInsightHTML(p, cur, prev, yoy, curRows);
}

/* ---- 데이터 로딩 확장: 기존(어필리에이트가 이미 감싼) loadLive()는 그대로 두고, 한 번 더 감싸서 coupon만 채운다 ---- */
function loadCouponFromJson_(json){
  const cells=(json&&json.sheets&&json.sheets.coupon)||[];
  DATA.coupon=parseCouponSheet(cells);
  initCouponControls();
}
const _rakutenCpOrigLoadLive=loadLive;
loadLive=async function(){
  await _rakutenCpOrigLoadLive();
  try{
    const json=await fetchGitHubData();
    loadCouponFromJson_(json);
  }catch(e){
    console.warn('[쿠폰 분석] 데이터 로드 실패 — 이전 상태 유지:', e.message);
  }
  if(activeTab===7) renderCoupon();
};
if(document.getElementById('refresh')) document.getElementById('refresh').onclick=loadLive;

initCouponControls();
/* ============================================================
   신규 기능(쿠폰 분석) 끝
   ============================================================ */

/* ============================================================
   신규 기능: AI 분석 메모 v2 (대시보드 전체 공통)
   — 메모는 탭 단위가 아니라 "탭 + 현재 선택된 조건(연도/월/프로모션/대상 등)"별로 각각 저장된다.
     예: 6월에 남긴 메모는 6월 컨텍스트에만 저장되고, 7월로 넘어가면 7월 전용 메모(없으면 빈 목록)가 보인다.
   — 항목마다 여러 개의 메모를 추가/수정/삭제할 수 있고, 작성 시각과 작성 순서를 그대로 유지한다.
   — AI 분석이 있는 탭(②③⑥⑦⑧)과 없는 탭(①④⑤) 모두 동일한 UI/저장 방식을 사용한다.
   — v1(rakutenDashMemo_, 탭당 메모 1개)과 데이터 구조가 달라 그대로 옮길 수 없어 새 접두사를
     사용한다 — 기존 v1 저장분은 더 이상 읽지 않는다(요청에 따라 유지 불필요).
   ============================================================ */
const MEMO_PREFIX='rakutenDashMemoV2_';
let memoEditingId=null; // 지금 인라인 편집 중인 메모 항목의 id (박스 하나당 동시에 최대 1개만 편집)

function memoEscapeHtml(s){
  return String(s==null?'':s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function memoFmtTime(iso){
  const d=new Date(iso); if(isNaN(d)) return '';
  const p=n=>String(n).padStart(2,'0');
  return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}
function memoStorageKey(tabKey, ctx){ return MEMO_PREFIX+tabKey+'::'+(ctx||'__default__'); }
function memoLoad(tabKey, ctx){
  try{
    const raw=localStorage.getItem(memoStorageKey(tabKey, ctx));
    const arr=raw? JSON.parse(raw) : [];
    return Array.isArray(arr)? arr : [];
  }catch(e){ return []; }
}
function memoSaveList(tabKey, ctx, list){ localStorage.setItem(memoStorageKey(tabKey, ctx), JSON.stringify(list)); }
function memoNewId(){ return 'm'+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }

/* 현재 선택 조건(context) — 탭별 상태 변수를 그대로 읽어 실제 화면에 렌더링된 값과 항상 일치시킨다. */
const memoCtxM=()=>(document.getElementById('m-month')||{}).value||'';
const memoCtxA=()=>(document.getElementById('a-promo')||{}).value||'';
const memoCtxD=()=>{const v=(document.getElementById('d-promo')||{}).value; return v? v+'::shop' : '';};
const memoCtxC=()=>(document.getElementById('c-base')||{}).value||'';
const memoCtxY=()=>(document.getElementById('y-year')||{}).value||'';
const memoCtxF=()=>(trafficState.promoId||'')+'::'+(trafficState.target||'');
const memoCtxAF=()=>affState.promoId||'';
const memoCtxCP=()=>(cpState.promoId||'')+'::'+(cpState.kind||'');

function renderMemoBox(tabKey, ctx){
  const box=document.querySelector(`.memo-box[data-memo-key="${tabKey}"]`); if(!box) return;
  box.dataset.memoCtx=ctx||'__default__';
  const body=box.querySelector('.memo-body'); if(!body) return;
  const list=memoLoad(tabKey, box.dataset.memoCtx);
  if(!list.length){ body.innerHTML='<div class="memo-empty muted-note">등록된 메모가 없습니다.</div>'; return; }
  body.innerHTML=list.map(m=>{
    if(m.id===memoEditingId){
      return `<div class="memo-entry" data-id="${m.id}">
        <textarea class="memo-edit-input">${memoEscapeHtml(m.text)}</textarea>
        <div class="memo-entry-actions">
          <button type="button" class="btn memo-save-btn" data-id="${m.id}">저장</button>
          <button type="button" class="btn memo-cancel-btn" data-id="${m.id}">취소</button>
        </div>
      </div>`;
    }
    const ts=(m.updatedAt && m.updatedAt!==m.createdAt) ? `${memoFmtTime(m.updatedAt)} (수정됨)` : memoFmtTime(m.createdAt);
    return `<div class="memo-entry" data-id="${m.id}">
      <div class="memo-entry-time muted-note">${ts}</div>
      <div class="memo-entry-text">${memoEscapeHtml(m.text).replace(/\n/g,'<br>')}</div>
      <div class="memo-entry-actions">
        <button type="button" class="btn memo-edit-btn" data-id="${m.id}">수정</button>
        <button type="button" class="btn memo-del-btn" data-id="${m.id}">삭제</button>
      </div>
    </div>`;
  }).join('');
}

function wireMemoBox(box){
  const tabKey=box.dataset.memoKey;
  const addBtn=box.querySelector('.memo-add-btn');
  const addWrap=box.querySelector('.memo-add-wrap');
  const addInput=box.querySelector('.memo-add-input');
  if(addBtn) addBtn.onclick=()=>{ addWrap.style.display='flex'; addInput.value=''; addInput.focus(); };
  const addSaveBtn=box.querySelector('.memo-add-save');
  const addCancelBtn=box.querySelector('.memo-add-cancel');
  if(addSaveBtn) addSaveBtn.onclick=()=>{
    const text=addInput.value.trim(); if(!text) return;
    const ctx=box.dataset.memoCtx;
    const list=memoLoad(tabKey, ctx);
    const now=new Date().toISOString();
    list.push({id:memoNewId(), text, createdAt:now, updatedAt:now});
    memoSaveList(tabKey, ctx, list);
    addWrap.style.display='none';
    renderMemoBox(tabKey, ctx);
  };
  if(addCancelBtn) addCancelBtn.onclick=()=>{ addWrap.style.display='none'; };

  const body=box.querySelector('.memo-body');
  if(body) body.onclick=(e)=>{
    const ctx=box.dataset.memoCtx;
    const editBtn=e.target.closest('.memo-edit-btn');
    const delBtn=e.target.closest('.memo-del-btn');
    const saveBtn=e.target.closest('.memo-save-btn');
    const cancelBtn=e.target.closest('.memo-cancel-btn');
    if(editBtn){ memoEditingId=editBtn.dataset.id; renderMemoBox(tabKey, ctx); }
    else if(cancelBtn){ memoEditingId=null; renderMemoBox(tabKey, ctx); }
    else if(delBtn){
      if(!confirm('이 메모를 삭제할까요?')) return;
      memoSaveList(tabKey, ctx, memoLoad(tabKey, ctx).filter(m=>m.id!==delBtn.dataset.id));
      renderMemoBox(tabKey, ctx);
    } else if(saveBtn){
      const id=saveBtn.dataset.id;
      const inputEl=body.querySelector(`.memo-entry[data-id="${id}"] .memo-edit-input`);
      const text=inputEl? inputEl.value.trim() : '';
      if(!text) return;
      const list=memoLoad(tabKey, ctx);
      const it=list.find(m=>m.id===id);
      if(it){ it.text=text; it.updatedAt=new Date().toISOString(); memoSaveList(tabKey, ctx, list); }
      memoEditingId=null;
      renderMemoBox(tabKey, ctx);
    }
  };
}
function initMemoBoxes(){
  document.querySelectorAll('.memo-box').forEach(box=>{
    if(box.dataset.memoWired) return;
    box.dataset.memoWired='1';
    wireMemoBox(box);
  });
  // 최초 진입 시 각 탭의 현재 컨텍스트로 한 번씩 렌더링(그 뒤로는 각 탭 render 함수가 갱신을 담당)
  renderMemoBox('monthly', memoCtxM());
  renderMemoBox('promo', memoCtxA());
  renderMemoBox('daily', memoCtxD());
  renderMemoBox('daily-cum', memoCtxD());
  renderMemoBox('daily-mainsku', memoCtxD());
  renderMemoBox('compare', memoCtxC());
  renderMemoBox('yearly', memoCtxY());
  renderMemoBox('traffic', memoCtxF());
  renderMemoBox('affiliate', memoCtxAF());
  renderMemoBox('coupon', memoCtxCP());
}
/* ============================================================
   신규 기능(메모) 끝
   ============================================================ */

/* boot */
initControls();setStatus('snap');renderAll();loadLive();initMemoBoxes();wireSkuGroupManager();wireSkuDayButtons();wireAddSkuManager();wireAddSkuGrid();

